const mysql = require('mysql2/promise');

const pool = mysql.createPool({
    host: process.env.DB_HOST || 'localhost',
    user: process.env.DB_USER || 'root',
    password: process.env.DB_PASSWORD || '',
    database: process.env.DB_NAME || 'lumina_crm',
    waitForConnections: true,
    connectionLimit: 10,
    queueLimit: 0
});

module.exports = pool;

const express = require('express');
const cors = require('cors');
const bodyParser = require('body-parser');
const db = require('./db');
const { v4: uuidv4 } = require('uuid');

const app = express();
app.use(cors());
app.use(bodyParser.json());

const PORT = process.env.PORT || 5000;

// --- AUTH ---
app.post('/api/auth/login', async (req, res) => {
    const { email, password } = req.body;
    try {
        const [rows] = await db.execute(
            'SELECT u.*, r.permissions FROM users u LEFT JOIN roles r ON u.role = r.name WHERE (u.email = ? OR u.username = ?) AND u.password = ? AND u.status = "Active"',
            [email, email, password]
        );
        if (rows.length > 0) {
            const user = rows[0];
            delete user.password;
            res.json({ success: true, user });
        } else {
            res.status(401).json({ success: false, message: 'Invalid credentials' });
        }
    } catch (err) {
        res.status(500).json({ error: err.message });
    }
});

// --- LEADS ---
app.get('/api/leads', async (req, res) => {
    try {
        const [rows] = await db.execute('SELECT * FROM leads ORDER BY created_at DESC');
        res.json(rows);
    } catch (err) {
        res.status(500).json({ error: err.message });
    }
});

app.post('/api/leads', async (req, res) => {
    const lead = { ...req.body, id: uuidv4() };
    const sql = `INSERT INTO leads (id, name, phone, email, service, country, lead_source, lead_status, application_status, passport_status, company_name, location, assigned_to_id) 
                 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`;
    const params = [lead.id, lead.name, lead.phone, lead.email, lead.service, lead.country, lead.leadSource, lead.leadStatus, lead.applicationStatus, lead.passportStatus, lead.companyName, lead.location, lead.assignedToId];
    try {
        await db.execute(sql, params);
        res.json({ success: true, lead });
    } catch (err) {
        res.status(500).json({ error: err.message });
    }
});

app.put('/api/leads/:id', async (req, res) => {
    const { id } = req.params;
    const l = req.body;
    const sql = `UPDATE leads SET name=?, phone=?, email=?, service=?, country=?, lead_source=?, lead_status=?, application_status=?, passport_status=?, company_name=?, location=?, assigned_to_id=? WHERE id=?`;
    const params = [l.name, l.phone, l.email, l.service, l.country, l.leadSource, l.leadStatus, l.applicationStatus, l.passportStatus, l.companyName, l.location, l.assignedToId, id];
    try {
        await db.execute(sql, params);
        res.json({ success: true });
    } catch (err) {
        res.status(500).json({ error: err.message });
    }
});

// --- CUSTOMERS ---
app.get('/api/customers', async (req, res) => {
