                 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`;
    const params = [cust.id, cust.customerId, cust.name, cust.phone, cust.email, cust.country, cust.companyName, cust.gstNumber, cust.location, cust.vendorId, cust.saleById, cust.serviceType, cust.closeDate, cust.action, cust.passportStatus];
