const express = require('express');
const cors = require('cors');
const bodyParser = require('body-parser');
const db = require('./db');

const app = express();
app.use(cors());
app.use(bodyParser.json());

const PORT = process.env.PORT || 5000;

// --- AUTH ---
app.post('/api/auth/login', async (req, res) => {
    const { email, password } = req.body;
    try {
        const [rows] = await db.execute(
            'SELECT u.*, r.permissions FROM users u LEFT JOIN roles r ON u.role_id = r.id WHERE (u.email = ? OR u.username = ?) AND u.password = ? AND u.status = "Active"',
            [email, email, password]
        );
        if (rows.length > 0) {
            const user = rows[0];
            delete user.password;
            res.json({ success: true, user });
        } else {
            res.status(401).json({ success: false, message: 'Invalid credentials' });
        }
    } catch (err) {
        res.status(500).json({ error: err.message });
    }
});

// --- LEADS ---
app.get('/api/leads', async (req, res) => {
    try {
        const [rows] = await db.execute('SELECT * FROM leads ORDER BY created_at DESC');
        res.json(rows);
    } catch (err) {
        res.status(500).json({ error: err.message });
    }
});

app.post('/api/leads', async (req, res) => {
    const lead = req.body;
    const sql = `INSERT INTO leads (name, phone, email, service, country, lead_source, lead_status, application_status, passport_status, company_name, location, assigned_to_id) 
                 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`;
    const params = [lead.name, lead.phone, lead.email, lead.service, lead.country, lead.leadSource, lead.leadStatus, lead.applicationStatus, lead.passportStatus, lead.companyName, lead.location, lead.assignedToId];
    try {
        const [result] = await db.execute(sql, params);
        res.json({ success: true, lead: { ...lead, id: result.insertId } });
    } catch (err) {
        res.status(500).json({ error: err.message });
    }
});

app.put('/api/leads/:id', async (req, res) => {
    const { id } = req.params;
    const l = req.body;
    const sql = `UPDATE leads SET name=?, phone=?, email=?, service=?, country=?, lead_source=?, lead_status=?, application_status=?, passport_status=?, company_name=?, location=?, assigned_to_id=? WHERE id=?`;
    const params = [l.name, l.phone, l.email, l.service, l.country, l.leadSource, l.leadStatus, l.applicationStatus, l.passportStatus, l.companyName, l.location, l.assignedToId, id];
    try {
        await db.execute(sql, params);
        res.json({ success: true });
    } catch (err) {
        res.status(500).json({ error: err.message });
    }
});

// --- CUSTOMERS ---
app.get('/api/customers', async (req, res) => {
    try {
        const [rows] = await db.execute('SELECT * FROM customers ORDER BY created_at DESC');
        res.json(rows);
    } catch (err) {
        res.status(500).json({ error: err.message });
    }
});

app.post('/api/customers', async (req, res) => {
    const cust = req.body;
    const sql = `INSERT INTO customers (customer_id_string, name, phone, email, country, company_name, gst_number, location, vendor_id, sale_by_id, service_type, close_date, action, passport_status) 
                 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`;
    const params = [cust.customerId, cust.name, cust.phone, cust.email, cust.country, cust.companyName, cust.gstNumber, cust.location, cust.vendorId, cust.saleById, cust.serviceType, cust.closeDate, cust.action, cust.passportStatus];
    try {
        const [result] = await db.execute(sql, params);
        res.json({ success: true, customer: { ...cust, id: result.insertId } });
    } catch (err) {
        res.status(500).json({ error: err.message });
    }
});

// --- CHAT ---
app.get('/api/chat/:userId1/:userId2', async (req, res) => {
    const { userId1, userId2 } = req.params;
    try {
        const [rows] = await db.execute(
            'SELECT * FROM chat_messages WHERE (sender_id = ? AND receiver_id = ?) OR (sender_id = ? AND receiver_id = ?) ORDER BY timestamp ASC',
            [userId1, userId2, userId2, userId1]
        );
        res.json(rows);
    } catch (err) {
        res.status(500).json({ error: err.message });
    }
});

app.post('/api/chat', async (req, res) => {
    const msg = req.body;
    try {
        const [result] = await db.execute(
            'INSERT INTO chat_messages (sender_id, receiver_id, content) VALUES (?, ?, ?)',
            [msg.senderId, msg.receiverId, msg.content]
        );
        res.json({ success: true, message: { ...msg, id: result.insertId } });
    } catch (err) {
        res.status(500).json({ error: err.message });
    }
});

// --- SETTINGS & CONFIG ---
app.get('/api/config/all', async (req, res) => {
    try {
        const [sources] = await db.execute('SELECT * FROM lead_sources');
        const [statuses] = await db.execute('SELECT * FROM lead_statuses');
        const [appStatuses] = await db.execute('SELECT * FROM application_statuses');
        const [passStatuses] = await db.execute('SELECT * FROM passport_statuses');
        const [docTypes] = await db.execute('SELECT * FROM document_types');
        const [users] = await db.execute('SELECT id, name, username, email, role_name as role, status, image_url FROM users');
        const [roles] = await db.execute('SELECT * FROM roles');
        const [vendors] = await db.execute('SELECT * FROM vendors');
        const [company] = await db.execute('SELECT * FROM company_details WHERE id = 1');

        res.json({
            leadSources: sources,
            leadStatuses: statuses,
            applicationStatuses: appStatuses,
            passportStatuses: passStatuses,
            documentTypes: docTypes,
            users,
            roles,
            vendors,
            companyDetails: company[0] || {}
        });
    } catch (err) {
        res.status(500).json({ error: err.message });
    }
});

app.listen(PORT, () => {
    console.log(`Backend server running on http://localhost:${PORT}`);
});

