    leadId: string | number;
    quoteNumber: string;
    createdAt: string;
    validUntil: string;
    status: QuoteStatus;
    items: QuoteItem[];
    subtotal: number;
    tax: number;
    total: number;
}

// Added LeadTableColumn interface
export interface LeadTableColumn {
  key: string;
  label: string;
}

export type TriggerModule = 'Lead';
export type TriggerEvent = 'updated';
export type TriggerField = 'leadStatus' | 'assignedToId';
export type ActionType = 'createReminder' | 'createNote';

export interface WorkflowRule {
    id: string | number;
    name: string;
    triggerModule: TriggerModule;
    triggerEvent: TriggerEvent;
    conditions: {
        field: TriggerField;
        value: string;
    }[];
    actionType: ActionType;
    actionDetails: {
        note?: string;
        dueInDays?: number;
    };
}

export interface ExportRequest {
  id: string | number;
  module: string;
  exportedBy: string;
  exportedTime: string;
  recordCount: number;
  status: 'Pending' | 'Completed' | 'Failed';
}

