  const handleExport = () => {
    fireToast('info', 'Starting export...');

    // Filter out 'actions' column for header
    const exportColumns = visibleColumns.filter(c => c.key !== 'actions');
    const headers = exportColumns.map(c => c.label).join(',');

    const rows = sortedLeads.map(lead => {
        return exportColumns.map(col => {
            let val = '';
            // FIX line 195: cast lead.id to string
            if (col.key === 'id_serial') val = String(lead.id);
            else if (col.key === 'assignedToId') val = users.find(u => u.id === lead.assignedToId)?.name || 'Unassigned';
            else val = (lead as any)[col.key] || ''; // Handle potential undefined

            // CSV Escaping: Wrap in quotes if contains comma, quote, or newline
            const stringVal = String(val);
            if (stringVal.includes(',') || stringVal.includes('"') || stringVal.includes('\n')) {
                return `"${stringVal.replace(/"/g, '""')}"`;
            }
            return stringVal;
        }).join(',');
    });

    const csvContent = "data:text/csv;charset=utf-8," + encodeURIComponent([headers, ...rows].join("\n"));
