            <div className="flex flex-col xl:flex-row gap-4 justify-between items-start xl:items-center">
                {/* Search and Filters */}
                <div className="flex-grow flex flex-col sm:flex-row gap-3 w-full xl:w-auto">
                    <SearchInput
