import React, { useState } from 'react';
import { useCrm } from '../../hooks/useCrm';

interface LeadRemindersProps {
    leadId: string;
}

const LeadReminders: React.FC<LeadRemindersProps> = ({ leadId }) => {
    const { getRemindersForLead, addReminderForLead, toggleReminderCompletion } = useCrm();
    const [note, setNote] = useState('');
    const [dueDate, setDueDate] = useState('');

    const reminders = getRemindersForLead(leadId);
    const upcoming = reminders.filter(r => !r.isCompleted);
    const completed = reminders.filter(r => r.isCompleted);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (note.trim() && dueDate) {
            addReminderForLead(leadId, note, new Date(dueDate).toISOString());
            setNote('');
            setDueDate('');
        }
    };

    return (
        <div>
            <form onSubmit={handleSubmit} className="mb-4 space-y-2">
                 <input
                    type="text"
                    value={note}
                    onChange={(e) => setNote(e.target.value)}
                    placeholder="Task or reminder note..."
                    className="block w-full rounded-md border-gray-300 shadow-sm focus:border-primary focus:ring-primary sm:text-sm p-2"
                />
                <input
                    type="datetime-local"
                    value={dueDate}
                    onChange={(e) => setDueDate(e.target.value)}
                    className="block w-full rounded-md border-gray-300 shadow-sm focus:border-primary focus:ring-primary sm:text-sm p-2"
                />
                <button type="submit" className="w-full mt-2 px-4 py-2 bg-primary text-white rounded-md hover:bg-primary/90 text-sm font-medium">
                    Set Task
                </button>
            </form>

            <div className="space-y-3 max-h-80 overflow-y-auto pr-2">
                <h4 className="text-sm font-semibold text-gray-600 mt-4">Upcoming</h4>
                {upcoming.length > 0 ? upcoming.map(r => (
                    <div key={r.id} className="flex items-start text-sm">
                        {/* FIX line 51: cast r.id to string */}
                        <input type="checkbox" checked={r.isCompleted} onChange={() => toggleReminderCompletion(String(r.id))} className="mt-1 mr-2 h-4 w-4 rounded border-gray-300 text-primary focus:ring-primary" />
                        <div>
                            <p className="text-gray-800">{r.note}</p>
                            <p className="text-xs text-primary">{new Date(r.dueDate).toLocaleString()}</p>
                        </div>
                    </div>
                )) : <p className="text-xs text-gray-500 pl-6">None</p>}

                <h4 className="text-sm font-semibold text-gray-600 mt-4 pt-2 border-t">Completed</h4>
                {completed.length > 0 ? completed.map(r => (
                     <div key={r.id} className="flex items-start text-sm opacity-60">
                        {/* FIX line 62: cast r.id to string */}
                        <input type="checkbox" checked={r.isCompleted} onChange={() => toggleReminderCompletion(String(r.id))} className="mt-1 mr-2 h-4 w-4 rounded border-gray-300 text-primary focus:ring-primary" />
                        <div>
                            <p className="text-gray-800 line-through">{r.note}</p>
                            <p className="text-xs text-gray-500">{new Date(r.dueDate).toLocaleString()}</p>
                        </div>
                    </div>
                )) : <p className="text-xs text-gray-500 pl-6">None</p>}
                 {reminders.length === 0 && <p className="text-gray-500 text-sm text-center py-4">No reminders for this lead.</p>}
            </div>
        </div>
    );
};

export default LeadReminders;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { useCrm } from '../hooks/useCrm';
import { useSwal } from '../hooks/useSwal';
import { generateAvatar } from '../utils/avatar';
import { User } from '../types';
import { capitalizeName } from '../utils/formatters';
import PageContainer from '../components/layout/PageContainer';

type TabView = 'personal' | 'security' | 'activity';

const ProfilePage: React.FC = () => {
  const { currentUser, updateProfile, leads, userActivityLogs } = useCrm();
  const { fireToast } = useSwal();
  const navigate = useNavigate();

  if (!currentUser) return null;

  const [activeTab, setActiveTab] = useState<TabView>('personal');

  // Profile Form State
  const [name, setName] = useState(capitalizeName(currentUser.name));
  const [email, setEmail] = useState(currentUser.email);
  const [imagePreview, setImagePreview] = useState<string | null>(currentUser.imageUrl || null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Security Form State
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [passwordError, setPasswordError] = useState('');

  useEffect(() => {
    setName(capitalizeName(currentUser.name));
    setEmail(currentUser.email);
    setImagePreview(currentUser.imageUrl || null);
  }, [currentUser]);

  // Stats Calculation
  const stats = useMemo(() => {
      const myLeads = leads.filter(l => String(l.assignedToId) === String(currentUser.id));
      const total = myLeads.length;
      const won = myLeads.filter(l => l.leadStatus === 'Won').length;
      const conversion = total > 0 ? Math.round((won / total) * 100) : 0;
      return { total, won, conversion };
  }, [leads, currentUser.id]);

  // Activity Logs
  const activityLogs = useMemo(() => {
      return userActivityLogs
        .filter(log => String(log.userId) === String(currentUser.id))
        .sort((a, b) => new Date(b.loginDate).getTime() - new Date(a.loginDate).getTime());
  }, [userActivityLogs, currentUser.id]);

  // Handlers
  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onloadend = () => setImagePreview(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleProfileUpdate = (e: React.FormEvent) => {
    e.preventDefault();
    if (name.trim() === '') return;

    const updatedData: Partial<User> = {};
    if (name !== currentUser.name) updatedData.name = name;
    if (email !== currentUser.email) updatedData.email = email;
    if (imagePreview !== currentUser.imageUrl) updatedData.imageUrl = imagePreview;

    if (Object.keys(updatedData).length > 0) {
      // Fix line 75: cast currentUser.id to string
      updateProfile(String(currentUser.id), updatedData);
      fireToast('success', 'Profile updated successfully');
    }
  };

  const handlePasswordUpdate = (e: React.FormEvent) => {
    e.preventDefault();
    setPasswordError('');
    if (!password) { setPasswordError('Please enter a new password.'); return; }
    if (password !== confirmPassword) { setPasswordError('Passwords do not match.'); return; }

    // Fix line 86: cast currentUser.id to string
    updateProfile(String(currentUser.id), { password });
    fireToast('success', 'Password changed successfully');
    setPassword('');
    setConfirmPassword('');
  };

  const avatarSrc = imagePreview || generateAvatar(name);

  const tabClass = (tabName: TabView) => 
    `whitespace-nowrap py-4 px-1 border-b-2 font-medium text-sm transition-colors ${
        activeTab === tabName
        ? 'border-primary text-primary'
        : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
    }`;

  return (
    <PageContainer>
      <div className="max-w-6xl mx-auto">
        <h1 className="text-2xl font-bold text-gray-800 mb-6">My Profile</h1>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">

          {/* LEFT SIDEBAR: Profile Card Only */}
          <div className="lg:col-span-4 space-y-6">

            {/* Profile Card */}
            <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
                <div className="p-8 text-center border-b border-gray-100">
                    <div className="relative inline-block mb-4">
                        <img 
                            src={avatarSrc} 
                            alt="Profile" 
                            className="w-32 h-32 rounded-full object-cover border-4 border-gray-50 shadow-sm" 
                        />
                        <button
                            onClick={() => fileInputRef.current?.click()}
                            className="absolute bottom-1 right-1 bg-white text-gray-600 p-2 rounded-full shadow border border-gray-200 hover:text-primary transition-colors"
                            title="Change Photo"
                        >
                            <i className="ri-camera-fill text-lg"></i>
                        </button>
                        <input type="file" ref={fileInputRef} onChange={handleImageChange} accept="image/*" className="hidden" />
                    </div>
                    <h2 className="text-xl font-bold text-gray-800 mb-1">{capitalizeName(currentUser.name)}</h2>

                    {/* Role Badge */}
                    <div className="mb-5">
                        <span className={`inline-flex items-center px-3 py-1 rounded-full text-xs font-medium border ${
                            currentUser.role === 'Super Admin' 
                            ? 'bg-primary/10 text-primary border-primary/20' 
                            : 'bg-blue-50 text-blue-700 border-blue-100'
                        }`}>
                            {currentUser.role}
                        </span>
                    </div>

                    <div className="flex justify-center gap-3">
                        <span className="px-3 py-1 bg-gray-100 text-gray-600 text-xs font-medium rounded-full border border-gray-200">
                            @{currentUser.username}
                        </span>
                        <span className="px-3 py-1 bg-green-50 text-green-700 text-xs font-medium rounded-full border border-green-100 flex items-center gap-1.5">
                            <span className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse"></span> Active
                        </span>
                    </div>
                </div>

                {/* Stats */}
                <div className="grid grid-cols-3 divide-x divide-gray-100 bg-gray-50/50">
                    <div className="p-4 text-center">
                        <p className="text-xl font-bold text-gray-800">{stats.total}</p>
                        <p className="text-[10px] text-gray-500 uppercase tracking-wide font-semibold">Leads</p>
                    </div>
                    <div className="p-4 text-center">
                        <p className="text-xl font-bold text-green-600">{stats.won}</p>
                        <p className="text-[10px] text-gray-500 uppercase tracking-wide font-semibold">Won</p>
                    </div>
                    <div className="p-4 text-center">
                        <p className="text-xl font-bold text-blue-600">{stats.conversion}%</p>
                        <p className="text-[10px] text-gray-500 uppercase tracking-wide font-semibold">Conv.</p>
                    </div>
                </div>
            </div>
          </div>

          {/* RIGHT CONTENT AREA: Tabs & Forms */}
