import React from 'react';
import { useCrm } from '../hooks/useCrm';
import { usePermissions } from '../hooks/usePermissions';
import { useSwal } from '../hooks/useSwal';
import { usePagination } from '../hooks/usePagination';
import Pagination from '../components/common/Pagination';
import { Vendor } from '../types';
import { useSorting } from '../hooks/useSorting';
import PageContainer from '../components/layout/PageContainer';
import Tooltip from '../components/common/Tooltip';

const VendorsPage: React.FC = () => {
  const { vendors, customers, openVendorModal, deleteVendor } = useCrm();
  const permissions = usePermissions();
  const { confirmDelete, fireToast } = useSwal();
  const canCreate = permissions.can('vendors', 'create');
  const canUpdate = permissions.can('vendors', 'update');
  const canDelete = permissions.can('vendors', 'delete');

  const { items: sortedVendors, requestSort, sortConfig } = useSorting<Vendor>(vendors, { key: 'name', direction: 'ascending'});

  const {
    paginatedData,
    currentPage,
    setCurrentPage,
    totalPages,
    itemsPerPage,
    setItemsPerPage,
    startIndex,
    endIndex,
    totalItems
  } = usePagination(sortedVendors, 10);

  const handleDelete = async (id: string | number, name: string) => {
    const associatedCustomersCount = customers.filter(c => String(c.vendorId) === String(id)).length;
    let html: React.ReactNode = <>Are you sure you want to delete the vendor "<strong>{name}</strong>"? This action cannot be undone.</>;

    if (associatedCustomersCount > 0) {
      html = (
        `
          <p>This vendor is currently assigned to <strong>${associatedCustomersCount} customer(s)</strong>.</p>
          <p class="mt-2 text-sm text-gray-500">Deleting "<strong>${name}</strong>" will leave these customer records without an assigned vendor. Are you sure you want to proceed?</p>
        `
      );
    }

    const result = await confirmDelete({
        title: 'Delete Vendor?',
        html: html,
    });

    if(result) {
        // Fix line 97: cast id to string
        deleteVendor(String(id));
        fireToast('success', `Vendor "${name}" deleted successfully.`);
    }
  }

  return (
    <PageContainer>
    <div className="container mx-auto">
      <div className="flex flex-wrap gap-4 justify-between items-center mb-6">
        <h2 className="text-2xl font-semibold text-gray-800">Vendors</h2>
        {canCreate && (
            <button onClick={() => openVendorModal(null)} className="px-4 py-2 text-sm font-medium text-white bg-primary rounded-md hover:bg-primary/90 flex items-center">
                <i className="ri-add-line mr-2"></i>
                Add Vendor
            </button>
        )}
      </div>
      <div className="bg-white rounded-lg shadow-md overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead className="bg-gray-50">
              <tr>
                <th className="p-4 text-left text-sm font-semibold text-gray-600 cursor-pointer hover:bg-gray-100 group" onClick={() => requestSort('name')}>
                  <div className="flex items-center">Vendor Name {sortConfig?.key === 'name' ? (<i className={`ml-1 ${sortConfig.direction === 'ascending' ? 'ri-arrow-up-s-line' : 'ri-arrow-down-s-line'}`}></i>) : (<i className="ml-1 text-gray-400 ri-arrow-up-down-line opacity-0 group-hover:opacity-100 transition-opacity"></i>)}</div>
                </th>
                {(canUpdate || canDelete) && <th className="p-4 text-left text-sm font-semibold text-gray-600">Actions</th>}
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200">
              {paginatedData.map((vendor: Vendor) => (
                <tr key={vendor.id} className="hover:bg-gray-50">
                  <td className="p-4 whitespace-nowrap font-medium text-gray-900">{vendor.name}</td>
                  {(canUpdate || canDelete) && (
                    <td className="p-4 whitespace-nowrap text-sm font-medium">
                        <div className="flex items-center space-x-1">
                            {canUpdate && (
                                <Tooltip content="Edit Vendor">
                                    <button onClick={() => openVendorModal(vendor)} className="p-2 text-gray-500 rounded-full hover:bg-gray-100 hover:text-primary transition-colors">
                                        <i className="ri-pencil-fill text-base"></i>
                                    </button>
                                </Tooltip>
                            )}
                            {canDelete && (
                                <Tooltip content="Delete Vendor">
                                    <button onClick={() => handleDelete(vendor.id, vendor.name)} className="p-2 text-gray-500 rounded-full hover:bg-gray-100 hover:text-red-500 transition-colors">
                                        <i className="ri-delete-bin-5-fill text-base"></i>
                                    </button>
                                </Tooltip>
                            )}
                        </div>
                    </td>
                  )}
                </tr>
              ))}
               {paginatedData.length === 0 && (
                <tr><td colSpan={2} className="text-center py-10 text-gray-500">No vendors found.</td></tr>
               )}
            </tbody>
          </table>
        </div>
        <Pagination
            currentPage={currentPage}
            totalPages={totalPages}
            onPageChange={setCurrentPage}
            itemsPerPage={itemsPerPage}
            onItemsPerPageChange={setItemsPerPage}
            totalItems={totalItems}
            startIndex={startIndex}
            endIndex={endIndex}
        />
      </div>
    </div>
    </PageContainer>
  );
};

export default VendorsPage;

import React, { useState, useRef } from 'react';
import { Lead, LeadDocument, DocumentStatus } from '../../types';
import { v4 as uuidv4 } from 'uuid';
import { useCrm } from '../../hooks/useCrm';
import { useSwal } from '../../hooks/useSwal';

interface LeadDocumentsProps {
    lead: Lead;
    setLead?: React.Dispatch<React.SetStateAction<Lead | null>>; // Optional/Deprecated
}

const getStatusClass = (status: DocumentStatus) => {
    switch (status) {
        case DocumentStatus.VERIFIED: return 'bg-green-100 text-green-800 border-green-200';
        case DocumentStatus.UPLOADED: return 'bg-blue-100 text-blue-800 border-blue-200';
        case DocumentStatus.REJECTED: return 'bg-red-100 text-red-800 border-red-200';
        case DocumentStatus.PENDING:
        default: return 'bg-gray-100 text-gray-800 border-gray-200';
    }
};

const LeadDocuments: React.FC<LeadDocumentsProps> = ({ lead }) => {
    const { updateLead, documentTypes } = useCrm();
    const { fireToast, confirmDelete } = useSwal();
    const [newDocName, setNewDocName] = useState('');
    const fileInputRef = useRef<HTMLInputElement>(null);
    const [docToUploadId, setDocToUploadId] = useState<string | null>(null);

    const handleAddDocument = (name: string) => {
        const trimmedName = name.trim();
        if (!trimmedName) return;

        if (lead.documents.some(doc => doc.name.toLowerCase() === trimmedName.toLowerCase())) {
            fireToast('warning', `Document "${trimmedName}" already exists.`);
            return;
        }

        const newDocument: LeadDocument = {
            id: uuidv4(),
            name: trimmedName,
            status: DocumentStatus.PENDING,
        };

        const updatedLead = {
            ...lead,
            documents: [...lead.documents, newDocument]
        };

        updateLead(updatedLead);
        setNewDocName('');
        fireToast('success', 'Document added successfully');
    };

    const handleDeleteDocument = async (docId: string | number, docName: string) => {
        const result = await confirmDelete({
            title: 'Remove Document?',
            html: `Are you sure you want to remove <strong>${docName}</strong>?`,
            confirmButtonText: 'Yes, remove'
        });

        if (result) {
            const updatedLead = {
                ...lead,
                documents: lead.documents.filter(d => String(d.id) !== String(docId))
            };
            updateLead(updatedLead);
            fireToast('success', 'Document removed');
        }
    };

    const handleStatusChange = (docId: string | number, newStatus: DocumentStatus) => {
         const updatedLead = {
            ...lead,
            documents: lead.documents.map(d => String(d.id) === String(docId) ? {...d, status: newStatus} : d)
        };
        updateLead(updatedLead);
    };

    const triggerFileUpload = (docId: string | number) => {
        // Fix line 180: cast docId to string
        setDocToUploadId(String(docId));
        fileInputRef.current?.click();
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0] && docToUploadId) {
            const file = e.target.files[0];
            const updatedLead = {
                ...lead,
                documents: lead.documents.map(d => 
                    // Fix line 190: cast d.id to string
                    String(d.id) === String(docToUploadId) 
                    ? { ...d, status: DocumentStatus.UPLOADED, fileName: file.name } 
                    : d
                )
            };
            updateLead(updatedLead);
            setDocToUploadId(null);
            e.target.value = ''; // Reset file input
            fireToast('success', 'File uploaded successfully');
        }
    };


    return (
        <div>
            {/* Add Custom Document */}
            <div className="flex gap-2 mb-6">
                <input
                    type="text"
                    value={newDocName}
                    onChange={(e) => setNewDocName(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleAddDocument(newDocName)}
                    placeholder="Type document name..."
                    className="flex-grow block w-full rounded-md border-gray-300 shadow-sm focus:border-primary focus:ring-primary text-sm p-2.5 bg-gray-50 focus:bg-white transition-colors"
                />
                <button 
                    onClick={() => handleAddDocument(newDocName)} 
                    disabled={!newDocName.trim()}
                    className="px-5 py-2.5 bg-gray-900 text-white rounded-md hover:bg-black text-sm font-medium disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                >
                    Add
                </button>
            </div>

            {/* Predefined List */}
            <div className="mb-6 bg-blue-50/50 p-4 rounded-lg border border-blue-100">
                <p className="text-xs font-bold text-gray-500 uppercase tracking-wide mb-3">Quick Add Documents:</p>
                <div className="flex flex-wrap gap-2">
                    {documentTypes.map(docType => {
                        const exists = lead.documents.some(d => d.name.toLowerCase() === docType.name.toLowerCase());
                        return (
                            <button 
                                key={docType.id} 
                                onClick={() => handleAddDocument(docType.name)} 
                                disabled={exists}
                                className={`px-3 py-1.5 rounded-full text-xs font-medium border transition-all duration-200 flex items-center gap-1 ${
                                    exists 
                                    ? 'bg-gray-100 text-gray-400 border-gray-200 cursor-not-allowed' 
                                    : 'bg-white text-gray-700 border-gray-300 hover:border-primary hover:text-primary hover:shadow-sm'
                                }`}
                            >
                                {exists ? <i className="ri-check-line"></i> : <i className="ri-add-line"></i>}
                                {docType.name}
                            </button>
                        );
                    })}
                </div>
            </div>

            {/* Document List */}
            <div className="space-y-3">
                {lead.documents.length > 0 ? lead.documents.map(doc => (
                    <div key={doc.id} className="bg-white border border-gray-200 p-4 rounded-lg shadow-sm hover:shadow-md transition-shadow">
                        <div className="flex justify-between items-start">
                             <div className="flex items-center gap-3">
                                 <div className={`w-10 h-10 rounded-lg flex items-center justify-center flex-shrink-0 ${doc.fileName ? 'bg-red-50 text-red-500' : 'bg-gray-100 text-gray-400'}`}>
                                     <i className={`${doc.fileName ? 'ri-file-pdf-fill' : 'ri-file-unknow-line'} text-xl`}></i>
                                 </div>
                                 <div>
                                     <p className="text-gray-800 text-sm font-semibold">{doc.name}</p>
                                     {doc.fileName ? (
                                        <p className="text-xs text-gray-500 mt-0.5 flex items-center gap-1">
                                            <i className="ri-attachment-line"></i> {doc.fileName}
                                        </p>
                                     ) : (
                                        <p className="text-xs text-gray-400 italic mt-0.5">No file attached</p>
                                     )}
                                 </div>
                             </div>

                             <div className="flex items-center gap-3">
                                <div className="relative group">
                                    <span className={`px-2.5 py-1 text-xs font-bold rounded border ${getStatusClass(doc.status)} cursor-pointer flex items-center gap-1`}>
                                        {doc.status} <i className="ri-arrow-down-s-line"></i>
                                    </span>
                                    <div className="absolute right-0 top-full mt-1 w-36 bg-white border rounded-lg shadow-xl opacity-0 group-hover:opacity-100 transition-opacity duration-200 z-10 pointer-events-none group-hover:pointer-events-auto overflow-hidden">
                                        {Object.values(DocumentStatus).map(s => (
                                            <button 
                                                key={s} 
                                                onClick={() => handleStatusChange(doc.id, s)} 
                                                className={`block w-full text-left px-4 py-2 text-xs hover:bg-gray-50 ${s === doc.status ? 'bg-gray-50 font-bold text-primary' : 'text-gray-700'}`}
                                            >
                                                {s}
                                            </button>
                                        ))}
                                    </div>
                                </div>

                                <button 
                                    // Fix line 201: cast doc.id to string
                                    onClick={() => handleDeleteDocument(String(doc.id), doc.name)} 
                                    className="w-8 h-8 flex items-center justify-center rounded-full text-gray-400 hover:text-red-600 hover:bg-red-50 transition-colors"
                                    title="Remove Document"
                                >
                                    <i className="ri-delete-bin-line text-lg"></i>
                                </button>
                            </div>
                        </div>

                        <div className="mt-4 pt-3 border-t border-gray-100 flex justify-end">
                             {doc.status === DocumentStatus.PENDING || doc.status === DocumentStatus.REJECTED ? (
                                 <button onClick={() => triggerFileUpload(doc.id)} className="text-xs font-medium text-primary hover:text-primary/80 flex items-center gap-1">
                                     <i className="ri-upload-2-line"></i> Upload File
                                 </button>
                             ) : (
                                 <button className="text-xs font-medium text-green-600 flex items-center gap-1 cursor-default">
                                     <i className="ri-check-double-line"></i> Uploaded
                                 </button>
                             )}
                        </div>
                    </div>
                )) : (
                    <div className="flex flex-col items-center justify-center py-10 border-2 border-dashed border-gray-200 rounded-lg text-gray-400 bg-gray-50/50">
                        <i className="ri-file-add-line text-4xl mb-2 text-gray-300"></i>
                        <p className="text-sm font-medium">No documents required yet.</p>
                        <p className="text-xs">Add a custom document or select from the quick list.</p>
                    </div>
                )}
            </div>
            <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" />
        </div>
    );
};

