      if (!currentUser) return [];
      return messages.filter(m => 
          (String(m.senderId) === String(currentUser.id) && String(m.receiverId) === String(userId)) ||
          (String(m.senderId) === String(userId) && String(m.receiverId) === String(currentUser.id))
