type Entity = SaleBy | WorkedBy;

interface EntityManagementProps {
  title: string;
  items: Entity[];
  onAdd: (data: Omit<Entity, 'id'>) => void;
  onUpdate: (data: Entity) => void;
  onDelete: (id: string) => void;
