                  <tr>
                    <td colSpan={5} className="text-center py-10 text-gray-500">No import history found.</td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
        <div className="flex justify-end space-x-3 bg-gray-50 p-4 rounded-b-lg">
          <button type="button" onClick={onClose} className="px-6 py-2 bg-gray-200 text-gray-800 rounded-md hover:bg-gray-300 text-sm font-medium">
            Close
          </button>
        </div>
      </div>
    </div>
  );
};

export default ImportHistoryModal;

import React, { useState, useEffect } from 'react';
import { useCrm } from '../../hooks/useCrm';
import { Quote, QuoteItem, QuoteStatus } from '../../types';
import { v4 as uuidv4 } from 'uuid';
import { useSwal } from '../../hooks/useSwal';

const QuoteBuilderModal: React.FC = () => {
    const {
        isQuoteBuilderOpen,
        closeQuoteBuilder,
        editingQuote,
        addQuote,
        updateQuote,
        currentLeadIdForQuote,
    } = useCrm();
    const { fireToast } = useSwal();

    const getInitialQuote = (): Omit<Quote, 'id' | 'leadId' | 'quoteNumber'> => ({
        createdAt: new Date().toISOString().split('T')[0],
        validUntil: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
        status: QuoteStatus.DRAFT,
        items: [{ id: uuidv4(), description: '', quantity: 1, price: 0, total: 0 }],
        subtotal: 0,
        tax: 10, // Default 10% tax
        total: 0,
    });

    const [quoteData, setQuoteData] = useState<Partial<Quote>>(getInitialQuote());

    useEffect(() => {
        if (isQuoteBuilderOpen) {
            if (editingQuote) {
                setQuoteData(editingQuote);
            } else {
                setQuoteData(getInitialQuote());
            }
        }
    }, [isQuoteBuilderOpen, editingQuote]);

    useEffect(() => {
        // Recalculate totals whenever items or tax change
        const subtotal = quoteData.items?.reduce((sum, item) => sum + item.total, 0) || 0;
        const taxAmount = subtotal * ((quoteData.tax || 0) / 100);
        const total = subtotal + taxAmount;
        setQuoteData(prev => ({...prev, subtotal, total}));
    }, [quoteData.items, quoteData.tax]);


    if (!isQuoteBuilderOpen) return null;

    const handleItemChange = (itemId: string, field: keyof QuoteItem, value: any) => {
        const newItems = quoteData.items?.map(item => {
            if (item.id === itemId) {
                const newItem = { ...item, [field]: value };
                if (field === 'quantity' || field === 'price') {
                    newItem.total = (newItem.quantity || 0) * (newItem.price || 0);
                }
                return newItem;
            }
            return item;
        });
        setQuoteData(prev => ({...prev, items: newItems}));
    };

    const handleAddItem = () => {
        const newItem: QuoteItem = { id: uuidv4(), description: '', quantity: 1, price: 0, total: 0 };
        setQuoteData(prev => ({...prev, items: [...(prev.items || []), newItem]}));
    };

    const handleRemoveItem = (itemId: string) => {
        if (quoteData.items && quoteData.items.length > 1) {
             setQuoteData(prev => ({...prev, items: prev.items?.filter(item => item.id !== itemId)}));
        }
    };

    const handleFieldChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value } = e.target;
        setQuoteData(prev => ({...prev, [name]: name === 'tax' ? parseFloat(value) : value }));
    };

    const handleSubmit = () => {
        if (currentLeadIdForQuote) {
            if (editingQuote) {
                // FIX: Ensure ID compatibility when updating
                updateQuote(quoteData as Quote);
            } else {
                // FIX: currentLeadIdForQuote is string | null, addQuote takes string | number
                addQuote(currentLeadIdForQuote, quoteData as Omit<Quote, 'id' | 'leadId' | 'quoteNumber'>);
            }
            closeQuoteBuilder();
            fireToast('success', editingQuote ? 'Quote updated!' : 'Quote created!');
        }
    };

    const handleDownload = () => {
        // Simulation for demo
        fireToast('info', 'Downloading Quote PDF...');
    }


    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 z-50 flex justify-center items-center p-4" onClick={closeQuoteBuilder}>
            <div className="bg-white rounded-lg shadow-xl w-full max-w-4xl relative max-h-[90vh] flex flex-col" onClick={e => e.stopPropagation()}>
                <div className="flex justify-between items-center p-4 border-b">
                    <h3 className="text-xl font-semibold">{editingQuote ? `Edit Quote ${editingQuote.quoteNumber}` : 'Create New Quote'}</h3>
                    <div className="flex items-center gap-2">
                        {editingQuote && (
                            <button onClick={handleDownload} className="text-gray-600 hover:text-primary mr-2" title="Download PDF">
                                <i className="ri-download-line text-xl"></i>
                            </button>
                        )}
                        <button onClick={closeQuoteBuilder} className="text-gray-500 hover:text-gray-800"><i className="ri-close-line text-2xl"></i></button>
                    </div>
                </div>
                <div className="flex-grow p-6 overflow-y-auto space-y-6">
                    {/* Header Fields */}
                    <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                        <div>
                            <label className="text-sm font-medium">Issue Date</label>
                            <input type="date" name="createdAt" value={quoteData.createdAt || ''} onChange={handleFieldChange} className="mt-1 input-field" />
                        </div>
                        <div>
                            <label className="text-sm font-medium">Valid Until</label>
                            <input type="date" name="validUntil" value={quoteData.validUntil || ''} onChange={handleFieldChange} className="mt-1 input-field" />
                        </div>
                        <div>
                            <label className="text-sm font-medium">Status</label>
                            <select name="status" value={quoteData.status} onChange={handleFieldChange} className="mt-1 input-field">
                                {Object.values(QuoteStatus).map(s => <option key={s} value={s}>{s}</option>)}
                            </select>
                        </div>
                    </div>

                    {/* Items Table */}
                    <div className="overflow-x-auto">
                        <table className="w-full text-sm">
                            <thead className="bg-gray-100">
                                <tr>
                                    <th className="p-2 text-left w-1/2">Description</th>
                                    <th className="p-2 text-left w-24">Quantity</th>
                                    <th className="p-2 text-left w-36">Price (₹)</th>
                                    <th className="p-2 text-left w-36">Total (₹)</th>
                                    <th className="p-2 w-10"></th>
                                </tr>
                            </thead>
                            <tbody>
                                {quoteData.items?.map(item => (
                                    <tr key={item.id}>
                                        <td className="p-1"><input type="text" value={item.description} onChange={e => handleItemChange(item.id, 'description', e.target.value)} placeholder="Service Description" className="input-field-sm"/></td>
                                        <td className="p-1"><input type="number" value={item.quantity} onChange={e => handleItemChange(item.id, 'quantity', parseFloat(e.target.value))} className="input-field-sm"/></td>
                                        <td className="p-1">
                                            <div className="relative">
                                                <span className="absolute left-2 top-1/2 -translate-y-1/2 text-gray-500">₹</span>
                                                <input type="number" value={item.price} onChange={e => handleItemChange(item.id, 'price', parseFloat(e.target.value))} className="input-field-sm pl-5"/>
                                            </div>
                                        </td>
                                        <td className="p-1"><input type="text" readOnly value={`₹${item.total.toFixed(2)}`} className="input-field-sm bg-gray-50 font-medium"/></td>
                                        <td className="p-1 text-center"><button onClick={() => handleRemoveItem(item.id)} className="text-gray-400 hover:text-red-500"><i className="ri-delete-bin-line"></i></button></td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                        <button onClick={handleAddItem} className="mt-2 px-3 py-1 text-sm bg-gray-200 hover:bg-gray-300 rounded-md">+ Add Item</button>
                    </div>

                    {/* Totals Section */}
                    <div className="flex justify-end">
                        <div className="w-full max-w-xs space-y-2">
                            <div className="flex justify-between items-center">
                                <span className="font-medium">Subtotal:</span>
                                <span>₹{(quoteData.subtotal || 0).toFixed(2)}</span>
                            </div>
                            <div className="flex justify-between items-center">
