import React, { useState, useMemo } from 'react';
import { useCrm } from '../../hooks/useCrm';
import { Lead, LeadNote, LeadReminder } from '../../types';
import { useSwal } from '../../hooks/useSwal';
import Tooltip from '../common/Tooltip';

type ActivityItem = {
    type: 'note' | 'reminder';
    date: Date;
    data: LeadNote | LeadReminder;
}

const LeadActivityTab: React.FC<{ lead: Lead }> = ({ lead }) => {
    const { getNotesForLead, addNoteForLead, updateNote, deleteNote, getRemindersForLead, addReminderForLead, updateReminder, deleteReminder, toggleReminderCompletion } = useCrm();
    const { confirmDelete, fireToast } = useSwal();
    const [inputType, setInputType] = useState<'note' | 'task'>('note');

    // Form states for new entry
    const [content, setContent] = useState('');
    const [dueDate, setDueDate] = useState('');

    // Editing states
    const [editingId, setEditingId] = useState<string | null>(null);
    const [editContent, setEditContent] = useState('');
    const [editDate, setEditDate] = useState('');

    // FIX: Cast lead.id to string
    const notes = getNotesForLead(String(lead.id));
    const reminders = getRemindersForLead(String(lead.id));

    const activities = useMemo(() => {
        const combined: ActivityItem[] = [
            ...notes.map(n => ({ type: 'note' as const, date: new Date(n.createdAt), data: n })),
            ...reminders.map(r => ({ type: 'reminder' as const, date: new Date(r.dueDate), data: r })),
        ];
        return combined.sort((a, b) => b.date.getTime() - a.date.getTime());
    }, [notes, reminders]);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!content.trim()) return;

        if (inputType === 'note') {
            // FIX: Cast lead.id to string
            addNoteForLead(String(lead.id), content.trim());
        } else {
            if (!dueDate) {
                alert('Please select a due date for the task');
                return;
            }
            // FIX: Cast lead.id to string
            addReminderForLead(String(lead.id), content.trim(), new Date(dueDate).toISOString());
            setDueDate('');
        }
        setContent('');
    };

    // --- Actions Handlers ---

    const handleEditClick = (activity: ActivityItem) => {
        // FIX: Cast activity.data.id to string
        setEditingId(String(activity.data.id));
        if (activity.type === 'note') {
            setEditContent((activity.data as LeadNote).content);
        } else {
            setEditContent((activity.data as LeadReminder).note);
            // Format date for datetime-local input
            const d = new Date((activity.data as LeadReminder).dueDate);
            d.setMinutes(d.getMinutes() - d.getTimezoneOffset());
            setEditDate(d.toISOString().slice(0, 16));
        }
    };

    const handleCancelEdit = () => {
        setEditingId(null);
        setEditContent('');
        setEditDate('');
    };

    const handleSaveEdit = (activity: ActivityItem) => {
        if (!editContent.trim()) return;

        if (activity.type === 'note') {
            updateNote(activity.data.id, editContent);
            fireToast('success', 'Note updated successfully');
        } else {
            if (!editDate) {
                fireToast('error', 'Please select a due date');
                return;
            }
            updateReminder(activity.data.id, editContent, new Date(editDate).toISOString());
            fireToast('success', 'Task updated successfully');
        }
        handleCancelEdit();
    };

    const handleDeleteClick = async (activity: ActivityItem) => {
        const result = await confirmDelete({
            title: `Delete ${activity.type === 'note' ? 'Note' : 'Task'}?`,
            html: `Are you sure you want to delete this ${activity.type}? This action cannot be undone.`
        });

        if (result) {
            if (activity.type === 'note') {
                deleteNote(activity.data.id);
            } else {
                deleteReminder(activity.data.id);
            }
            fireToast('success', 'Item deleted');
        }
    };

    return (
        <div className="flex flex-col h-full">
            {/* New Activity Input Area */}
            <div className="mb-8">
                <div className="bg-gray-50 border border-gray-200 rounded-xl p-1 shadow-sm">
                    <div className="flex gap-2 p-2 border-b border-gray-200/60 mb-2">
                        <button 
                            onClick={() => setInputType('note')} 
                            className={`flex items-center gap-2 px-3 py-1.5 text-sm font-medium rounded-md transition-colors ${inputType === 'note' ? 'bg-white text-gray-800 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
                        >
                            <i className="ri-sticky-note-line"></i> Note
                        </button>
                        <button 
                            onClick={() => setInputType('task')} 
                            className={`flex items-center gap-2 px-3 py-1.5 text-sm font-medium rounded-md transition-colors ${inputType === 'task' ? 'bg-white text-gray-800 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
                        >
                            <i className="ri-task-line"></i> Task
                        </button>
                    </div>

                    <form onSubmit={handleSubmit} className="px-2 pb-2">
                        <textarea 
                            value={content} 
                            onChange={e => setContent(e.target.value)} 
                            placeholder={inputType === 'note' ? "Write a note about this lead..." : "What needs to be done?"}
                            rows={3} 
                            className="w-full bg-transparent border-0 focus:ring-0 text-sm text-gray-800 placeholder-gray-400 resize-none p-2"
                        />

                        <div className="flex justify-between items-center mt-2 pt-2 border-t border-gray-200/60">
                            <div className="flex items-center gap-2">
                                {inputType === 'task' && (
                                    <input 
                                        type="datetime-local" 
                                        value={dueDate} 
                                        onChange={e => setDueDate(e.target.value)} 
                                        className="text-xs border border-gray-300 rounded px-2 py-1 bg-white text-gray-600 focus:outline-none focus:border-primary"
                                    />
                                )}
                            </div>
                            <button 
                                type="submit" 
                                disabled={!content.trim()}
                                className="bg-gray-900 text-white px-4 py-1.5 rounded-lg text-sm font-medium hover:bg-black transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                            >
                                {inputType === 'note' ? 'Add Note' : 'Create Task'}
                            </button>
                        </div>
                    </form>
                </div>
            </div>

            {/* Timeline */}
            <div className="flex-grow">
                <h4 className="text-sm font-bold text-gray-900 mb-6 flex items-center gap-2">
                    <i className="ri-history-line"></i> Activity Timeline
                </h4>

                <div className="relative border-l-2 border-gray-100 ml-3.5 space-y-8 pb-4">
                    {activities.length > 0 ? activities.map(activity => (
                        <div key={activity.data.id} className="relative pl-8 group">
                            {/* Dot on Timeline */}
                            <div className={`absolute -left-[9px] top-0 h-5 w-5 rounded-full border-4 border-white shadow-sm flex items-center justify-center z-10 ${
                                activity.type === 'note' ? 'bg-blue-500' : 'bg-orange-500'
                            }`}>
                            </div>

                            {/* Card Content */}
                            <div className="flex flex-col sm:flex-row sm:justify-between sm:items-start gap-1">
                                <div className="flex-1 w-full">
                                    <div className="flex items-center justify-between mb-1">
                                        <div className="flex items-center gap-2">
                                            <span className={`text-xs font-bold px-2 py-0.5 rounded ${
                                                activity.type === 'note' ? 'bg-blue-50 text-blue-700' : 'bg-orange-50 text-orange-700'
                                            }`}>
                                                {activity.type === 'note' ? 'NOTE' : 'TASK'}
                                            </span>
                                            <span className="text-xs text-gray-400">
                                                {activity.date.toLocaleString([], { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })}
                                            </span>
                                        </div>

                                        {/* Actions (Edit/Delete) - Only show if not editing */}
                                        {editingId !== String(activity.data.id) && (
                                            <div className="flex gap-4 opacity-0 group-hover:opacity-100 transition-opacity">
                                                <Tooltip content="Edit">
                                                    <button onClick={() => handleEditClick(activity)} className="p-1 text-gray-400 hover:text-blue-600 transition-colors">
                                                        <i className="ri-pencil-line text-lg"></i>
                                                    </button>
                                                </Tooltip>
                                                <Tooltip content="Delete">
                                                    <button onClick={() => handleDeleteClick(activity)} className="p-1 text-gray-400 hover:text-red-600 transition-colors">
                                                        <i className="ri-delete-bin-line text-lg"></i>
                                                    </button>
                                                </Tooltip>
                                            </div>
                                        )}
                                    </div>

                                    <div className="bg-gray-50 rounded-lg p-3 border border-gray-100 hover:border-gray-200 transition-colors">

                                        {/* Editing Mode */}
                                        {editingId === String(activity.data.id) ? (
                                            <div className="space-y-3">
                                                <textarea
                                                    value={editContent}
                                                    onChange={e => setEditContent(e.target.value)}
                                                    className="w-full text-sm border border-gray-300 rounded p-2 focus:ring-1 focus:ring-primary focus:border-primary"
                                                    rows={3}
                                                />
                                                {activity.type === 'reminder' && (
                                                    <input
                                                        type="datetime-local"
                                                        value={editDate}
                                                        onChange={e => setEditDate(e.target.value)}
                                                        className="w-full text-xs border border-gray-300 rounded p-2"
                                                    />
                                                )}
                                                <div className="flex justify-end gap-2">
                                                    <button onClick={handleCancelEdit} className="text-xs px-3 py-1.5 bg-white border border-gray-300 rounded text-gray-600 hover:bg-gray-50">Cancel</button>
                                                    <button onClick={() => handleSaveEdit(activity)} className="text-xs px-3 py-1.5 bg-primary text-white rounded hover:bg-primary/90">Save</button>
                                                </div>
                                            </div>
                                        ) : (
                                            // Display Mode
                                            activity.type === 'note' ? (
                                                <>
                                                    <p className="text-sm text-gray-800 whitespace-pre-wrap">{(activity.data as LeadNote).content}</p>
                                                    <div className="mt-2 text-xs text-gray-400 font-medium">
                                                        Added by {(activity.data as LeadNote).author}
                                                    </div>
                                                </>
                                            ) : (
                                                <div className="flex items-start gap-3">
                                                    <div className="pt-0.5">
                                                        <input 
                                                            type="checkbox" 
                                                            checked={(activity.data as LeadReminder).isCompleted} 
                                                            onChange={() => toggleReminderCompletion(activity.data.id)} 
                                                            className="h-4 w-4 rounded border-gray-300 text-primary focus:ring-primary cursor-pointer" 
                                                        />
                                                    </div>
                                                    <div className="flex-1">
                                                        <p className={`text-sm font-medium ${(activity.data as LeadReminder).isCompleted ? 'line-through text-gray-400' : 'text-gray-800'}`}>
                                                            {(activity.data as LeadReminder).note}
                                                        </p>
                                                        <p className={`text-xs mt-1 font-medium ${
                                                            new Date((activity.data as LeadReminder).dueDate) < new Date() && !(activity.data as LeadReminder).isCompleted 
                                                            ? 'text-red-600' 
                                                            : 'text-gray-500'
                                                        }`}>
                                                            <i className="ri-calendar-event-line mr-1"></i>
                                                            Due: {new Date((activity.data as LeadReminder).dueDate).toLocaleString()}
                                                        </p>
                                                    </div>
                                                </div>
                                            )
                                        )}
                                    </div>
                                </div>
                            </div>
                        </div>
                    )) : (
                        <div className="ml-4 py-8 flex flex-col items-center justify-center text-center text-gray-400">
                            <div className="w-12 h-12 bg-gray-50 rounded-full flex items-center justify-center mb-3">
                                <i className="ri-chat-history-line text-2xl"></i>
                            </div>
                            <p className="text-sm">No activity recorded yet.</p>
                            <p className="text-xs">Add a note or task to get started.</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default LeadActivityTab;

import React, { useState, useMemo, useEffect } from 'react';
import { useCrm } from '../../hooks/useCrm';
import { useSwal } from '../../hooks/useSwal';
import { useSorting } from '../../hooks/useSorting';
import SearchInput from '../common/SearchInput';
import Tooltip from '../common/Tooltip';

interface StatusItem {
    // FIX: Allow id to be string or number to accommodate various CRM data types
    id: string | number;
    name: string;
}

interface StatusManagerProps {
    title: string;
    items: StatusItem[];
    onAdd: (name: string) => void;
    onUpdate: (item: StatusItem) => void;
    // FIX: Match signature to allow string or number id
    onDelete: (id: string | number) => void;
}

const StatusManager: React.FC<StatusManagerProps> = ({ title, items, onAdd, onUpdate, onDelete }) => {
    const { fireToast, confirmDelete } = useSwal();
    const [name, setName] = useState('');
    const [editingItem, setEditingItem] = useState<StatusItem | null>(null);
    const [searchTerm, setSearchTerm] = useState('');

    const { items: sortedItems, requestSort, sortConfig } = useSorting<StatusItem>(items, { key: 'name', direction: 'ascending' });

    useEffect(() => {
        if (!editingItem) {
            setName('');
        }
    }, [editingItem]);

    const filteredItems = useMemo(() => {
        return sortedItems.filter(item => item.name.toLowerCase().includes(searchTerm.toLowerCase()));
    }, [sortedItems, searchTerm]);

    const handleEditClick = (item: StatusItem) => {
        setEditingItem(item);
        setName(item.name);
    };

    const handleCancelEdit = () => {
        setEditingItem(null);
        setName('');
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (name.trim() === '') return;

        if (editingItem) {
            onUpdate({ ...editingItem, name });
            fireToast('success', `${title} updated successfully.`);
        } else {
            onAdd(name);
            fireToast('success', `${title} added successfully.`);
        }
        handleCancelEdit();
    };

    const handleDeleteClick = async (item: StatusItem) => {
        const result = await confirmDelete({
            title: `Delete ${title}?`,
            html: `Are you sure you want to delete "<strong>${item.name}</strong>"? This action cannot be undone.`,
        });
        if (result) {
            onDelete(item.id);
            fireToast('success', `${title} "${item.name}" deleted.`);
        }
    };

    return (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-1 bg-white p-6 rounded-lg shadow-md h-fit">
                <h3 className="text-lg font-semibold text-gray-800 border-b pb-2 mb-4">{editingItem ? `Edit ${title}` : `Add ${title}`}</h3>
                <form onSubmit={handleSubmit} className="space-y-4">
                    <div>
                        <label className="block text-sm font-medium text-gray-700">Name <span className="text-primary">*</span></label>
                        <input
                            type="text"
                            value={name}
                            onChange={(e) => setName(e.target.value)}
                            className="mt-1 w-full border border-gray-300 rounded-md shadow-sm p-2 text-sm focus:ring-primary focus:border-primary"
                            required
                            placeholder={`Enter ${title} name`}
                        />
                    </div>
                    <div className="flex space-x-2">
                        <button type="submit" className="px-4 py-2 bg-primary text-white font-semibold rounded-md hover:bg-primary/90 text-sm w-full">
                            {editingItem ? 'Update' : 'Submit'}
                        </button>
                        {editingItem && (
                            <button type="button" onClick={handleCancelEdit} className="px-4 py-2 bg-gray-200 text-gray-800 rounded-md hover:bg-gray-300 text-sm">
                                Cancel
                            </button>
                        )}
                    </div>
                </form>
            </div>

            <div className="lg:col-span-2 bg-white p-6 rounded-lg shadow-md">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="text-lg font-semibold">{title} List</h3>
                    <SearchInput
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        placeholder="Search..."
                        className="w-full max-w-xs"
                    />
                </div>
                <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                        <thead className="bg-gray-100">
                            <tr>
                                <th className="p-3 text-left font-semibold text-gray-600">S.No</th>
                                <th className="p-3 text-left font-semibold text-gray-600 cursor-pointer hover:bg-gray-100 group" onClick={() => requestSort('name')}>
                                    <div className="flex items-center">Name {sortConfig?.key === 'name' ? (<i className={`ml-1 ${sortConfig.direction === 'ascending' ? 'ri-arrow-up-s-line' : 'ri-arrow-down-s-line'}`}></i>) : (<i className="ml-1 text-gray-400 ri-arrow-up-down-line opacity-0 group-hover:opacity-100 transition-opacity"></i>)}</div>
                                </th>
                                <th className="p-3 text-left font-semibold text-gray-600">Action</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-200">
                            {filteredItems.map((item, index) => (
                                <tr key={item.id}>
                                    <td className="p-3 text-gray-600">{index + 1}</td>
                                    <td className="p-3 font-medium text-gray-800">{item.name}</td>
                                    <td className="p-3">
                                        <div className="flex items-center space-x-1">
                                            <Tooltip content={`Edit ${title}`}>
                                                <button onClick={() => handleEditClick(item)} className="p-2 text-gray-500 rounded-full hover:bg-gray-100 hover:text-primary transition-colors">
                                                    <i className="ri-pencil-fill text-base"></i>
                                                </button>
                                            </Tooltip>
                                            <Tooltip content={`Delete ${title}`}>
                                                <button onClick={() => handleDeleteClick(item)} className="p-2 text-gray-500 rounded-full hover:bg-gray-100 hover:text-red-500 transition-colors">
                                                    <i className="ri-delete-bin-5-fill text-base"></i>
                                                </button>
                                            </Tooltip>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                            {filteredItems.length === 0 && (
                                <tr><td colSpan={3} className="text-center py-6 text-gray-500">No items found.</td></tr>
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

const CRMConfiguration: React.FC = () => {
    const [activeTab, setActiveTab] = useState<'pipeline' | 'application' | 'passport' | 'document' | 'remark' | 'source' | 'service' | 'lost'>('pipeline');
    const { 
        leadStatuses, addLeadStatus, updateLeadStatus, deleteLeadStatus,
        applicationStatuses, addApplicationStatus, updateApplicationStatus, deleteApplicationStatus,
        passportStatuses, addPassportStatus, updatePassportStatus, deletePassportStatus,
        documentTypes, addDocumentType, updateDocumentType, deleteDocumentType,
        remarkStatuses, addRemarkStatus, updateRemarkStatus, deleteRemarkStatus,
        leadSources, addLeadSource, updateLeadSource, deleteLeadSource,
        serviceTypes, addServiceType, updateServiceType, deleteServiceType,
        lostReasons, addLostReason, updateLostReason, deleteLostReason,
    } = useCrm();

    const tabClass = (tabName: string) => {
        const isActive = activeTab === tabName;
        return `px-4 py-2 text-sm font-medium rounded-md cursor-pointer transition-colors whitespace-nowrap ${
            isActive ? 'bg-primary text-white' : 'bg-zinc-200 text-zinc-700 hover:bg-zinc-300'
        }`;
    };

    const renderContent = () => {
        switch (activeTab) {
            case 'pipeline':
                return <StatusManager title="Pipeline Status" items={leadStatuses} onAdd={addLeadStatus} onUpdate={updateLeadStatus} onDelete={deleteLeadStatus} />;
            case 'application':
                return <StatusManager title="Application Status" items={applicationStatuses} onAdd={addApplicationStatus} onUpdate={updateApplicationStatus} onDelete={deleteApplicationStatus} />;
            case 'passport':
                return <StatusManager title="Passport Status" items={passportStatuses} onAdd={addPassportStatus} onUpdate={updatePassportStatus} onDelete={deletePassportStatus} />;
            case 'document':
                return <StatusManager title="Document List" items={documentTypes} onAdd={addDocumentType} onUpdate={updateDocumentType} onDelete={deleteDocumentType} />;
            case 'remark':
                return <StatusManager title="Remark Status" items={remarkStatuses} onAdd={addRemarkStatus} onUpdate={updateRemarkStatus} onDelete={deleteRemarkStatus} />;
            case 'source':
                return <StatusManager title="Lead Source" items={leadSources} onAdd={addLeadSource} onUpdate={updateLeadSource} onDelete={deleteLeadSource} />;
            case 'service':
                return <StatusManager title="Service Type" items={serviceTypes} onAdd={addServiceType} onUpdate={updateServiceType} onDelete={deleteServiceType} />;
            case 'lost':
                return <StatusManager title="Lost Reason" items={lostReasons} onAdd={addLostReason} onUpdate={updateLostReason} onDelete={deleteLostReason} />;
            default:
                return null;
        }
    };

    return (
        <div className="container mx-auto">
            <div className="flex space-x-2 mb-6 p-2 bg-white rounded-lg shadow-sm w-full overflow-x-auto thin-scrollbar">
                <button onClick={() => setActiveTab('pipeline')} className={tabClass('pipeline')}>Pipeline Status</button>
                <button onClick={() => setActiveTab('application')} className={tabClass('application')}>Application Status</button>
                <button onClick={() => setActiveTab('passport')} className={tabClass('passport')}>Passport Status</button>
                <button onClick={() => setActiveTab('document')} className={tabClass('document')}>Document List</button>
                <button onClick={() => setActiveTab('remark')} className={tabClass('remark')}>Remark Status</button>
                <button onClick={() => setActiveTab('source')} className={tabClass('source')}>Lead Source</button>
                <button onClick={() => setActiveTab('service')} className={tabClass('service')}>Service Type</button>
                <button onClick={() => setActiveTab('lost')} className={tabClass('lost')}>Lost Reason</button>
            </div>
            <div>
                {renderContent()}
            </div>
            <style>{`
                .thin-scrollbar::-webkit-scrollbar { height: 6px; }
                .thin-scrollbar::-webkit-scrollbar-track { background: transparent; }
                .thin-scrollbar::-webkit-scrollbar-thumb { background: #d1d5db; border-radius: 3px; }
            `}</style>
        </div>
    );
};

export default CRMConfiguration;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { useCrm } from '../../hooks/useCrm';

interface CommandPaletteProps {
  isOpen: boolean;
  onClose: () => void;
}

type SearchResult = {
  id: string;
  type: 'lead' | 'customer' | 'page' | 'action';
  title: string;
  subtitle?: string;
  icon: string;
  action: () => void;
  tag?: string;
};

const CommandPalette: React.FC<CommandPaletteProps> = ({ isOpen, onClose }) => {
  const [query, setQuery] = useState('');
  const [selectedIndex, setSelectedIndex] = useState(0);
  const inputRef = useRef<HTMLInputElement>(null);
  const listRef = useRef<HTMLUListElement>(null);
  const navigate = useNavigate();
  const { leads, customers, openLeadModal, openInvoiceModal } = useCrm();

  // Focus input when opened
  useEffect(() => {
    if (isOpen) {
      setTimeout(() => inputRef.current?.focus(), 50);
    } else {
        setQuery('');
        setSelectedIndex(0);
    }
  }, [isOpen]);

  const filteredResults = useMemo(() => {
    if (!query) return [];

    const lowerQuery = query.toLowerCase();
    const results: SearchResult[] = [];

    // 1. Pages Navigation
    const pages = [
      { name: 'Dashboard', path: '/', icon: 'ri-dashboard-line' },
      { name: 'Leads', path: '/leads', icon: 'ri-group-line' },
      { name: 'Customers', path: '/customers', icon: 'ri-team-line' },
      { name: 'Invoices', path: '/invoices', icon: 'ri-file-list-3-line' },
      { name: 'Settings', path: '/settings', icon: 'ri-settings-3-line' },
      { name: 'Reminders', path: '/reminders', icon: 'ri-notification-3-line' },
    ];

    pages.forEach(page => {
      if (page.name.toLowerCase().includes(lowerQuery)) {
        results.push({
          id: `page-${page.name}`,
          type: 'page',
          title: page.name,
          subtitle: 'Go to page',
          icon: page.icon,
          action: () => navigate(page.path),
        });
      }
    });

    // 2. Actions
    if ('create lead'.includes(lowerQuery) || 'add lead'.includes(lowerQuery)) {
        results.push({
            id: 'action-create-lead',
            type: 'action',
            title: 'Create New Lead',
            subtitle: 'Action',
            icon: 'ri-user-add-line',
            action: () => openLeadModal(null)
        });
    }
    if ('create invoice'.includes(lowerQuery) || 'add invoice'.includes(lowerQuery)) {
        results.push({
            id: 'action-create-invoice',
            type: 'action',
            title: 'Create New Invoice',
            subtitle: 'Action',
            icon: 'ri-file-add-line',
            action: () => openInvoiceModal(null)
        });
    }

    // 3. Leads
    leads.forEach(lead => {
      if (lead.name.toLowerCase().includes(lowerQuery) || lead.phone.includes(lowerQuery)) {
        results.push({
          // FIX: Cast lead.id to string
          id: String(lead.id),
          type: 'lead',
          title: lead.name,
          subtitle: `${lead.phone} • ${lead.leadStatus}`,
          icon: 'ri-user-star-line',
          tag: 'Lead',
          action: () => navigate(`/leads/${lead.id}`),
        });
      }
    });

    // 4. Customers
    customers.forEach(cust => {
      if (cust.name.toLowerCase().includes(lowerQuery)) {
        results.push({
          // FIX: Cast cust.id to string
          id: String(cust.id),
          type: 'customer',
          title: cust.name,
          subtitle: `${cust.serviceType}`,
          icon: 'ri-briefcase-line',
          tag: 'Customer',
          action: () => navigate(`/customers`), // Ideally navigate to detail if exists
        });
      }
    });

    return results.slice(0, 10); // Limit to 10 results
  }, [query, leads, customers, navigate, openLeadModal, openInvoiceModal]);

  // Keyboard Navigation
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!isOpen) return;

      if (e.key === 'ArrowDown') {
        e.preventDefault();
        setSelectedIndex(prev => (prev + 1) % filteredResults.length);
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        setSelectedIndex(prev => (prev - 1 + filteredResults.length) % filteredResults.length);
      } else if (e.key === 'Enter') {
        e.preventDefault();
        if (filteredResults[selectedIndex]) {
          filteredResults[selectedIndex].action();
          onClose();
        }
      } else if (e.key === 'Escape') {
        onClose();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, filteredResults, selectedIndex, onClose]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[60] flex items-start justify-center pt-[15vh] px-4" onClick={onClose}>
      {/* Backdrop */}
      <div className="fixed inset-0 bg-gray-900/50 backdrop-blur-sm transition-opacity"></div>

      {/* Palette Window */}
      <div 
        className="relative w-full max-w-xl bg-white rounded-xl shadow-2xl overflow-hidden ring-1 ring-black/5 transform transition-all scale-100"
        onClick={e => e.stopPropagation()}
      >
        {/* Input */}
        <div className="flex items-center border-b border-gray-100 px-4 py-3 bg-gray-50/50">
          <i className="ri-search-line text-gray-400 text-xl mr-3"></i>
          <input
            ref={inputRef}
            type="text"
            className="flex-grow bg-transparent border-none outline-none text-gray-800 placeholder-gray-400 text-lg h-10"
            placeholder="What are you looking for?"
            value={query}
            onChange={e => {
                setQuery(e.target.value);
                setSelectedIndex(0);
            }}
          />
          <div className="flex items-center space-x-2">
             <span className="text-xs text-gray-400 bg-white border border-gray-200 rounded px-1.5 py-0.5">ESC</span>
          </div>
        </div>

        {/* Results List */}
        {filteredResults.length > 0 ? (
          <ul ref={listRef} className="max-h-[60vh] overflow-y-auto py-2">
            {filteredResults.map((result, index) => (
              <li
                key={result.id}
                onClick={() => {
                  result.action();
                  onClose();
                }}
                onMouseEnter={() => setSelectedIndex(index)}
                className={`px-4 py-3 mx-2 rounded-lg cursor-pointer flex items-center transition-colors group ${
                  index === selectedIndex ? 'bg-primary/5' : 'hover:bg-gray-50'
                }`}
              >
                <div className={`w-9 h-9 rounded-lg flex items-center justify-center mr-3 text-lg flex-shrink-0 transition-colors ${
                    index === selectedIndex ? 'bg-primary text-white shadow-sm' : 'bg-gray-100 text-gray-500'
                }`}>
                  <i className={result.icon}></i>
                </div>
                <div className="flex-grow min-w-0">
                  <div className={`font-medium ${index === selectedIndex ? 'text-gray-900' : 'text-gray-700'}`}>
                    {result.title}
                  </div>
                  {result.subtitle && (
                    <div className="text-xs text-gray-400 truncate">
                      {result.subtitle}
                    </div>
                  )}
                </div>
                {result.tag && (
                    <span className="text-xs font-medium text-gray-400 bg-gray-100 px-2 py-0.5 rounded border border-gray-200 mr-2">{result.tag}</span>
                )}
                {index === selectedIndex && (
                    <i className="ri-arrow-right-line text-primary"></i>
                )}
              </li>
            ))}
          </ul>
        ) : query ? (
          <div className="p-12 text-center text-gray-500">
            <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-gray-100 mb-4">
                <i className="ri-search-eye-line text-3xl text-gray-400"></i>
            </div>
            <p className="text-gray-600 font-medium">No results found</p>
            <p className="text-sm text-gray-400 mt-1">We couldn't find anything matching "{query}"</p>
          </div>
        ) : (
          <div className="p-12 text-center">
             <p className="text-gray-400 text-sm">Type to search leads, customers, or run commands.</p>
             <div className="flex justify-center gap-4 mt-4">
                <span className="text-xs text-gray-400 bg-gray-100 px-2 py-1 rounded">Search Leads</span>
                <span className="text-xs text-gray-400 bg-gray-100 px-2 py-1 rounded">Go to Settings</span>
                <span className="text-xs text-gray-400 bg-gray-100 px-2 py-1 rounded">Create Invoice</span>
             </div>
          </div>
        )}

        {/* Footer */}
        <div className="bg-gray-50 px-4 py-2 text-xs text-gray-400 flex justify-between items-center border-t border-gray-100">
            <div className="flex items-center gap-4">
                <span className="flex items-center"><i className="ri-arrow-up-line mr-1"></i><i className="ri-arrow-down-line mr-1"></i> to navigate</span>
                <span className="flex items-center"><i className="ri-corner-down-left-line mr-1"></i> to select</span>
            </div>
            <span>Lumina CRM</span>
        </div>
      </div>
    </div>
  );
};

export default CommandPalette;

