export const CrmContext = createContext<CrmContextType | undefined>(undefined);

export const CrmProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('crm_currentUser');
    return saved ? JSON.parse(saved) : null;
  });

  const [isLoading, setIsLoading] = useState(true);
  const [users, setUsers] = useState<User[]>([]);
  const [leads, setLeads] = useState<Lead[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [roles, setRoles] = useState<Role[]>([]);
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [leadNotes, setLeadNotes] = useState<LeadNote[]>([]);
  const [leadReminders, setLeadReminders] = useState<LeadReminder[]>([]);
  const [companyDetails, setCompanyDetails] = useState<CompanyDetails>(MockData.mockCompanyDetails);
  const [messages, setMessages] = useState<ChatMessage[]>([]);

  const [leadStatuses, setLeadStatuses] = useState<LeadStatus[]>([]);
  const [leadSources, setLeadSources] = useState<LeadSource[]>([]);
  const [applicationStatuses, setApplicationStatuses] = useState<ApplicationStatusItem[]>([]);
  const [passportStatuses, setPassportStatuses] = useState<PassportStatusItem[]>([]);
  const [documentTypes, setDocumentTypes] = useState<DocumentType[]>([]);
  const [remarkStatuses, setRemarkStatuses] = useState<RemarkStatus[]>([]);
  const [serviceTypes, setServiceTypes] = useState<ServiceType[]>([]);
  const [lostReasons, setLostReasons] = useState<LostReason[]>([]);

  const [isLeadModalOpen, setIsLeadModalOpen] = useState(false);
  const [editingLead, setEditingLead] = useState<Lead | null>(null);
  const [isInvoiceModalOpen, setIsInvoiceModalOpen] = useState(false);
  const [editingInvoice, setEditingInvoice] = useState<Invoice | null>(null);
  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [isRoleModalOpen, setIsRoleModalOpen] = useState(false);
  const [editingRole, setEditingRole] = useState<Role | null>(null);
  const [isVendorModalOpen, setIsVendorModalOpen] = useState(false);
  const [editingVendor, setEditingVendor] = useState<Vendor | null>(null);
  const [isQuoteBuilderOpen, setIsQuoteBuilderOpen] = useState(false);
  const [editingQuote, setEditingQuote] = useState<Quote | null>(null);
  const [currentLeadIdForQuote, setCurrentLeadIdForQuote] = useState<string | null>(null);

  // Missing state initializers
  const [systemLogs, setSystemLogs] = useState<SystemLog[]>([]);
  const [userActivityLogs, setUserActivityLogs] = useState<UserActivityLog[]>([]);
  const [saleBy, setSaleBy] = useState<SaleBy[]>([]);
  const [workedBy, setWorkedBy] = useState<WorkedBy[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [announcements, setAnnouncements] = useState<Announcement[]>([]);
  const [workflowRules, setWorkflowRules] = useState<WorkflowRule[]>([]);
  const [isWorkflowModalOpen, setIsWorkflowModalOpen] = useState(false);
  const [editingWorkflow, setEditingWorkflow] = useState<WorkflowRule | null>(null);
  const [permissionCategories, setPermissionCategories] = useState<PermissionCategory[]>([]);
  const [permissionSections, setPermissionSections] = useState<PermissionSection[]>([]);
  const [importedLeadFiles, setImportedLeadFiles] = useState<ImportedFile[]>([]);
  const [importedContactFiles, setImportedContactFiles] = useState<ImportedFile[]>([]);
  const [targets, setTargets] = useState<Target[]>([]);
  const [emailApiCredentials, setEmailApiCredentials] = useState<EmailApiCredentials>(MockData.mockEmailApiCredentials);
  const [mobileApiCredentials, setMobileApiCredentials] = useState<MobileApiCredentials>(MockData.mockMobileApiCredentials);
  const [quotes, setQuotes] = useState<Quote[]>(MockData.mockQuotes);
  const [emails, setEmails] = useState<Email[]>(MockData.mockEmails);
  const [whatsappMessages, setWhatsappMessages] = useState<WhatsAppMessage[]>(MockData.mockWhatsAppMessages);

  const fetchData = useCallback(async () => {
    setIsLoading(true);
    try {
      const [leadsData, customersData, invoicesData, configData] = await Promise.all([
        api.leads.getAll(),
        api.customers.getAll(),
        api.invoices.getAll(),
        api.config.init()
      ]);

      setLeads(leadsData);
      setCustomers(customersData);
      setInvoices(invoicesData);
      setUsers(configData.users);
      setRoles(configData.roles);
      setVendors(configData.vendors);
      setLeadSources(configData.leadSources);
      setLeadStatuses(configData.leadStatuses);
      setApplicationStatuses(configData.applicationStatuses);
      setPassportStatuses(configData.passportStatuses);
      setDocumentTypes(configData.documentTypes);
      if (configData.companyDetails) setCompanyDetails(configData.companyDetails);

      // Populate missing fields from MockData for now as a fallback
      setSystemLogs(MockData.mockSystemLogs);
      setUserActivityLogs(MockData.mockUserActivityLogs);
      setSaleBy(MockData.mockSaleBy);
      setWorkedBy(MockData.mockWorkedBy);
      setNotifications(MockData.mockNotifications);
      setAnnouncements(MockData.mockAnnouncements);
      setWorkflowRules(MockData.mockWorkflowRules);
      setPermissionCategories(MockData.mockPermissionCategories);
      setPermissionSections(MockData.mockPermissionSections);
      setImportedLeadFiles(MockData.mockImportedLeadFiles);
      setTargets([]);
      setRemarkStatuses(MockData.mockRemarkStatuses);
      setServiceTypes(MockData.mockServiceTypes);
      setLostReasons(MockData.mockLostReasons);

    } catch (err) {
      console.error('Failed to sync with Lumina Server:', err);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => { if (currentUser) fetchData(); }, [currentUser, fetchData]);

  const login = async (email: string, password?: string) => {
    try {
        const res = await api.auth.login({ email, password });
        if (res.success) {
            setCurrentUser(res.user);
            localStorage.setItem('crm_currentUser', JSON.stringify(res.user));
            return true;
        }
        return false;
    } catch (err) { return false; }
  };

  const logout = () => {
    setCurrentUser(null);
    localStorage.removeItem('crm_currentUser');
  };

  const addLead = async (data: any) => { await api.leads.create(data); await fetchData(); };
  const updateLead = async (data: Lead) => { await api.leads.update(data.id, data); await fetchData(); };
  const bulkAssignLeads = async (ids: any[], userId: any) => { await Promise.all(ids.map(id => api.leads.update(id, { assignedToId: userId }))); await fetchData(); };
  const bulkDeleteLeads = async (ids: any[]) => { await Promise.all(ids.map(id => api.leads.delete(id))); await fetchData(); };
  const bulkUpdateLeadStatus = async (ids: any[], status: string) => { await Promise.all(ids.map(id => api.leads.update(id, { leadStatus: status }))); await fetchData(); };
  const convertLeadToCustomer = async (lead: Lead) => { /* conversion logic */ await fetchData(); };

  const addCustomer = async (data: any) => { await api.customers.create(data); await fetchData(); };
  const updateCustomer = async (data: Customer) => { await api.customers.update(data.id, data); await fetchData(); };
  const deleteCustomer = async (id: any) => { await api.customers.delete(id); await fetchData(); };

  const addInvoice = async (data: any) => { await api.invoices.create(data); await fetchData(); };
  const updateInvoice = async (data: Invoice) => { await api.invoices.update(data.id, data); await fetchData(); };
  const deleteInvoice = async (id: any) => { await api.invoices.delete(id); await fetchData(); };

  const addUser = async (data: any) => { /* user crud implementation */ await fetchData(); };
  const updateUser = async (data: User) => { /* user crud implementation */ await fetchData(); };
  const deleteUser = async (id: any) => { /* user crud implementation */ await fetchData(); };
  const updateProfile = async (userId: any, data: any) => { /* profile update implementation */ await fetchData(); };
  const getUserActivityLogs = (userId: any) => userActivityLogs.filter(l => String(l.userId) === String(userId));

  const addNoteForLead = async (leadId: any, content: string) => {
    if (!currentUser) return;
    await api.leads.addNote(leadId, { content, author: currentUser.name });
    const notes = await api.leads.getNotes(leadId);
    setLeadNotes(prev => [...prev.filter(n => String(n.leadId) !== String(leadId)), ...notes]);
  };
  const updateNote = async (id: any, content: string) => { /* update note implementation */ await fetchData(); };
  const deleteNote = async (id: any) => { /* delete note implementation */ await fetchData(); };

  const addReminderForLead = async (leadId: any, note: string, dueDate: string) => {
    await api.leads.addReminder(leadId, { note, dueDate });
    const reminders = await api.leads.getReminders(leadId);
    setLeadReminders(prev => [...prev.filter(r => String(r.leadId) !== String(leadId)), ...reminders]);
  };
  const updateReminder = async (id: any, note: string, dueDate: string) => { /* update reminder implementation */ await fetchData(); };
  const deleteReminder = async (id: any) => { /* delete reminder implementation */ await fetchData(); };

  const toggleReminderCompletion = async (id: any) => {
    await api.leads.toggleReminder(id);
    setLeadReminders(prev => prev.map(r => String(r.id) === String(id) ? { ...r, isCompleted: !r.isCompleted } : r));
  };

  const sendMessage = async (receiverId: any, content: string) => {
    if (!currentUser) return;
    await api.chat.sendMessage({ senderId: currentUser.id, receiverId, content });
    setMessages(prev => [...prev, { id: uuidv4(), senderId: currentUser.id, receiverId, content, timestamp: new Date().toISOString(), isRead: false }]);
  };

  const markMessagesAsRead = async (userId: any) => {
    setMessages(prev => prev.map(m => String(m.senderId) === String(userId) ? { ...m, isRead: true } : m));
  };

  const getUnreadMessageCountForUser = (userId: any) => messages.filter(m => String(m.senderId) === String(userId) && !m.isRead).length;
  const getLastMessageForUser = (userId: any) => {
    const userMsgs = messages.filter(m => String(m.senderId) === String(userId) || String(m.receiverId) === String(userId));
    return userMsgs[userMsgs.length - 1];
  };

  const getMessagesWithUser = useCallback((userId: any) => {
      if (!currentUser) return [];
      return messages.filter(m => (String(m.senderId) === String(currentUser.id) && String(m.receiverId) === String(userId)) || (String(m.senderId) === String(userId) && String(m.receiverId) === String(currentUser.id)));
  }, [currentUser, messages]);

  const openLeadModal = (lead: Lead | null) => { setEditingLead(lead); setIsLeadModalOpen(true); };
  const closeLeadModal = () => { setIsLeadModalOpen(false); setEditingLead(null); };

  const openVendorModal = (v: Vendor | null) => { setEditingVendor(v); setIsVendorModalOpen(true); };
  const closeVendorModal = () => setIsVendorModalOpen(false);
  const addVendor = async (data: any) => { /* implementation */ await fetchData(); };
  const updateVendor = async (data: Vendor) => { /* implementation */ await fetchData(); };
  const deleteVendor = async (id: any) => { /* implementation */ await fetchData(); };

  const openRoleModal = (r: Role | null) => { setEditingRole(r); setIsRoleModalOpen(true); };
  const closeRoleModal = () => setIsRoleModalOpen(false);
  const addRole = async (data: any) => { /* implementation */ await fetchData(); };
  const updateRole = async (data: Role) => { /* implementation */ await fetchData(); };
  const deleteRole = async (id: any) => { /* implementation */ await fetchData(); };

  const getQuotesForLead = (leadId: any) => quotes.filter(q => String(q.leadId) === String(leadId));
  const openQuoteBuilder = (leadId: any, quote?: Quote | null) => { setCurrentLeadIdForQuote(String(leadId)); setEditingQuote(quote || null); setIsQuoteBuilderOpen(true); };
  const closeQuoteBuilder = () => setIsQuoteBuilderOpen(false);
  const addQuote = async (leadId: any, quote: any) => { /* implementation */ setQuotes(prev => [...prev, { ...quote, id: uuidv4(), leadId, quoteNumber: `QT-${Date.now()}` }]); };
  const updateQuote = async (quote: Quote) => { /* implementation */ setQuotes(prev => prev.map(q => q.id === quote.id ? quote : q)); };

  const updateCompanyDetails = async (details: CompanyDetails) => { await api.config.updateCompany(details); await fetchData(); };
  const updateEmailApiCredentials = async (creds: EmailApiCredentials) => { setEmailApiCredentials(creds); };
  const updateMobileApiCredentials = async (creds: MobileApiCredentials) => { setMobileApiCredentials(creds); };

  const addSaleBy = async (data: any) => { /* implementation */ await fetchData(); };
  const updateSaleBy = async (data: SaleBy) => { /* implementation */ await fetchData(); };
  const deleteSaleBy = async (id: any) => { /* implementation */ await fetchData(); };
  const addWorkedBy = async (data: any) => { /* implementation */ await fetchData(); };
  const updateWorkedBy = async (data: WorkedBy) => { /* implementation */ await fetchData(); };
  const deleteWorkedBy = async (id: any) => { /* implementation */ await fetchData(); };

  const markNotificationAsRead = async (id: any) => { setNotifications(prev => prev.map(n => n.id === id ? { ...n, isRead: true } : n)); };

  const addAnnouncement = async (data: any) => { setAnnouncements(prev => [...prev, { ...data, id: uuidv4(), authorId: currentUser?.id, scheduledAt: data.scheduledAt || new Date().toISOString() }]); };

  const openWorkflowModal = (rule: WorkflowRule | null) => { setEditingWorkflow(rule); setIsWorkflowModalOpen(true); };
  const closeWorkflowModal = () => setIsWorkflowModalOpen(false);
  const addWorkflowRule = async (data: any) => { setWorkflowRules(prev => [...prev, { ...data, id: uuidv4() }]); };
  const updateWorkflowRule = async (data: WorkflowRule) => { setWorkflowRules(prev => prev.map(r => r.id === data.id ? data : r)); };
  const deleteWorkflowRule = async (id: any) => { setWorkflowRules(prev => prev.filter(r => r.id !== id)); };

  const addPermissionCategory = async (cat: any) => { setPermissionCategories(prev => [...prev, { ...cat, id: uuidv4() }]); };
  const updatePermissionCategory = async (cat: PermissionCategory) => { setPermissionCategories(prev => prev.map(c => c.id === cat.id ? cat : c)); };
  const deletePermissionCategory = async (id: any) => { setPermissionCategories(prev => prev.filter(c => c.id !== id)); };
  const addPermissionSection = async (sec: any) => { setPermissionSections(prev => [...prev, { ...sec, id: uuidv4() }]); };
  const updatePermissionSection = async (sec: PermissionSection) => { setPermissionSections(prev => prev.map(s => s.id === sec.id ? sec : s)); };
  const deletePermissionSection = async (id: any) => { setPermissionSections(prev => prev.filter(s => s.id !== id)); };

  const importLeads = async (file: File, defaults: any) => { /* implementation */ await fetchData(); };
  const deleteImportedLeadFile = async (id: any) => { setImportedLeadFiles(prev => prev.filter(f => f.id !== id)); };
  const addTarget = async (target: any) => { setTargets(prev => [...prev, { ...target, id: uuidv4(), userName: users.find(u => String(u.id) === String(target.userId))?.name }]); };

  const addLeadStatus = async (name: string) => { setLeadStatuses(prev => [...prev, { id: uuidv4(), name }]); };
  const updateLeadStatus = async (item: LeadStatus) => { setLeadStatuses(prev => prev.map(s => s.id === item.id ? item : s)); };
  const deleteLeadStatus = async (id: any) => { setLeadStatuses(prev => prev.filter(s => s.id !== id)); };

  const addApplicationStatus = async (name: string) => { setApplicationStatuses(prev => [...prev, { id: uuidv4(), name }]); };
  const updateApplicationStatus = async (item: ApplicationStatusItem) => { setApplicationStatuses(prev => prev.map(s => s.id === item.id ? item : s)); };
  const deleteApplicationStatus = async (id: any) => { setApplicationStatuses(prev => prev.filter(s => s.id !== id)); };

  const addPassportStatus = async (name: string) => { setPassportStatuses(prev => [...prev, { id: uuidv4(), name }]); };
  const updatePassportStatus = async (item: PassportStatusItem) => { setPassportStatuses(prev => prev.map(s => s.id === item.id ? item : s)); };
  const deletePassportStatus = async (id: any) => { setPassportStatuses(prev => prev.filter(s => s.id !== id)); };

  const addDocumentType = async (name: string) => { setDocumentTypes(prev => [...prev, { id: uuidv4(), name }]); };
  const updateDocumentType = async (item: DocumentType) => { setDocumentTypes(prev => prev.map(s => s.id === item.id ? item : s)); };
  const deleteDocumentType = async (id: any) => { setDocumentTypes(prev => prev.filter(s => s.id !== id)); };

  const addRemarkStatus = async (name: string) => { setRemarkStatuses(prev => [...prev, { id: uuidv4(), name }]); };
  const updateRemarkStatus = async (item: RemarkStatus) => { setRemarkStatuses(prev => prev.map(s => s.id === item.id ? item : s)); };
  const deleteRemarkStatus = async (id: any) => { setRemarkStatuses(prev => prev.filter(s => s.id !== id)); };

