const express = require('express');
const cors = require('cors');
const bodyParser = require('body-parser');
require('dotenv').config();

const leadRoutes = require('./routes/leadRoutes');
const customerRoutes = require('./routes/customerRoutes');
const userRoutes = require('./routes/userRoutes');
const invoiceRoutes = require('./routes/invoiceRoutes');
const chatRoutes = require('./routes/chatRoutes');
const masterRoutes = require('./routes/masterRoutes');
const configRoutes = require('./routes/configRoutes');

const app = express();
app.use(cors());
app.use(bodyParser.json({ limit: '50mb' }));

// Modular Routes
app.use('/api/leads', leadRoutes);
app.use('/api/customers', customerRoutes);
app.use('/api/users', userRoutes);
app.use('/api/invoices', invoiceRoutes);
app.use('/api/chat', chatRoutes);
app.use('/api/master', masterRoutes);
app.use('/api/config', configRoutes);

// Auth helper route (kept simple as per request)
const db = require('./db');
app.post('/api/auth/login', async (req, res) => {
    const { email, password } = req.body;
    try {
        const [rows] = await db.execute(
            'SELECT u.*, r.permissions FROM users u LEFT JOIN roles r ON u.role_id = r.id WHERE (u.email = ? OR u.username = ?) AND u.password = ? AND u.status = "Active"',
            [email, email, password]
        );
        if (rows.length > 0) {
            const user = rows[0];
            delete user.password;
            res.json({ success: true, user });
        } else {
            res.status(401).json({ success: false, message: 'Invalid credentials' });
        }
    } catch (err) {
        res.status(500).json({ error: err.message });
    }
});

const PORT = process.env.PORT || 5000;
app.listen(PORT, () => {
    console.log(`Lumina CRM Enterprise Server running on port ${PORT}`);
});

