exports.convertToCustomer = async (req, res) => {
    const { id } = req.params;
    const { customerIdString, saleById, closeDate } = req.body;
    const connection = await db.getConnection();
    try {
        await connection.beginTransaction();
        const [[lead]] = await connection.execute('SELECT * FROM leads WHERE id = ?', [id]);
        if (!lead) throw new Error('Lead not found');

        const sql = `INSERT INTO customers (customer_id_string, name, phone, email, country, company_name, location, sale_by_id, close_date, passport_status) 
                     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`;
        await connection.execute(sql, [customerIdString, lead.name, lead.phone, lead.email, lead.country, lead.company_name, lead.location, saleById, closeDate, lead.passport_status]);
        await connection.execute('UPDATE leads SET lead_status = "Won" WHERE id = ?', [id]);

        await connection.commit();
        res.json({ success: true });
    } catch (err) {
        await connection.rollback();
        res.status(500).json({ error: err.message });
    } finally { connection.release(); }
};

