router.get('/all', async (req, res) => {
    try {
        const queries = [
            'SELECT * FROM lead_sources',
            'SELECT * FROM lead_statuses',
            'SELECT * FROM application_statuses',
            'SELECT * FROM passport_statuses',
            'SELECT * FROM document_types',
            'SELECT * FROM remark_statuses',
