    getMessagesWithUser, sendMessage, getTotalUnreadMessages: () => messages.filter(m => !m.isRead && String(m.receiverId) === String(currentUser?.id)).length,
    markMessagesAsRead, getUnreadMessageCountForUser, getLastMessageForUser,
