app.post('/api/auth/login', async (req, res) => {
    const { email, password } = req.body;
    try {
        const [rows] = await db.execute(
            'SELECT u.*, r.permissions FROM users u LEFT JOIN roles r ON u.role_id = r.id WHERE (u.email = ? OR u.username = ?) AND u.password = ? AND u.status = "Active"',
            [email, email, password]
        );
        if (rows.length > 0) {
            const user = rows[0];
            delete user.password;
            res.json({ success: true, user });
        } else {
            res.status(401).json({ success: false, message: 'Invalid credentials or account inactive.' });
        }
    } catch (err) {
        res.status(500).json({ error: err.message });
    }
});

