    openInvoiceModal: (i) => { setEditingInvoice(i); setIsInvoiceModalOpen(true); }, closeInvoiceModal: () => setIsInvoiceModalOpen(false), 
    addInvoice, updateInvoice, deleteInvoice,
    openUserModal: (u) => { setEditingUser(u); setIsUserModalOpen(true); }, closeUserModal: () => setIsUserModalOpen(false), 
    addUser, updateUser, deleteUser, updateProfile, getUserActivityLogs,
    getNotesForLead, addNoteForLead, updateNote, deleteNote,
    getRemindersForLead, addReminderForLead, updateReminder, deleteReminder, toggleReminderCompletion,
    getMessagesWithUser, sendMessage, getTotalUnreadMessages: () => messages.filter(m => !m.isRead && String(m.receiverId) === String(currentUser?.id)).length,
    markMessagesAsRead: async () => {}, getUnreadMessageCountForUser: () => 0, getLastMessageForUser: () => undefined,
    openVendorModal, closeVendorModal, addVendor, updateVendor, deleteVendor,
    openRoleModal, closeRoleModal, addRole, updateRole, deleteRole,
    getQuotesForLead, openQuoteBuilder, closeQuoteBuilder, addQuote, updateQuote,
