const jwt = require('jsonwebtoken');

module.exports = (req, res, next) => {
    const authHeader = req.headers['authorization'];
    const token = authHeader && authHeader.split(' ')[1];

    if (!token) {
        return res.status(401).json({ success: false, message: 'Access denied. No token provided.' });
    }

    try {
        const decoded = jwt.verify(token, process.env.JWT_SECRET || 'lumina_secret_key_2025');
        req.user = decoded;
        next();
    } catch (err) {
        res.status(403).json({ success: false, message: 'Invalid or expired token.' });
    }
};

const db = require('../db');
const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');

exports.login = async (req, res) => {
    const { email, password } = req.body;

    try {
        // Find user by email or username
        const [rows] = await db.execute(
            'SELECT u.*, r.permissions FROM users u LEFT JOIN roles r ON u.role_id = r.id WHERE (u.email = ? OR u.username = ?) AND u.status = "Active"',
            [email, email]
        );

        if (rows.length === 0) {
            return res.status(401).json({ success: false, message: 'Invalid credentials.' });
        }

        const user = rows[0];

        // Verify password (in a real migration, passwords would be hashed. 
        // For compatibility with existing seed data 'password123', we check both)
        const isMatch = await bcrypt.compare(password, user.password).catch(() => false);
        const isPlainMatch = password === user.password; // Fallback for initial seed data

        if (!isMatch && !isPlainMatch) {
            return res.status(401).json({ success: false, message: 'Invalid credentials.' });
        }

        // Generate JWT
        const token = jwt.sign(
            { id: user.id, role: user.role_name, email: user.email },
            process.env.JWT_SECRET || 'lumina_secret_key_2025',
            { expiresIn: '8h' }
        );

        // Prepare user object for frontend (remove sensitive data)
        const userResponse = { ...user };
        delete userResponse.password;

        res.json({
            success: true,
            token,
            user: userResponse
        });
    } catch (err) {
        console.error('Login error:', err);
        res.status(500).json({ success: false, message: 'Server error during authentication.' });
    }
};

exports.me = async (req, res) => {
    try {
        const [rows] = await db.execute(
            'SELECT u.id, u.name, u.username, u.email, u.role_name, u.status, u.image_url, r.permissions FROM users u LEFT JOIN roles r ON u.role_id = r.id WHERE u.id = ?',
            [req.user.id]
        );
        if (rows.length === 0) return res.status(404).json({ message: 'User not found' });
        res.json(rows[0]);
    } catch (err) {
        res.status(500).json({ error: err.message });
    }
};

