const db = require('../db');
const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');

exports.login = async (req, res) => {
    const { email, password } = req.body;

    try {
        // Find user by email or username
        const [rows] = await db.execute(
            'SELECT u.*, r.permissions FROM users u LEFT JOIN roles r ON u.role_id = r.id WHERE (u.email = ? OR u.username = ?) AND u.status = "Active"',
            [email, email]
        );

        if (rows.length === 0) {
            return res.status(401).json({ success: false, message: 'Invalid credentials.' });
        }

        const user = rows[0];

        // Verify password
        const isMatch = await bcrypt.compare(password, user.password).catch(() => false);
        const isPlainMatch = password === user.password; // Fallback for initial seed data

        if (!isMatch && !isPlainMatch) {
            return res.status(401).json({ success: false, message: 'Invalid credentials.' });
        }

        // Generate JWT
        const token = jwt.sign(
            { id: user.id, role: user.role_name, email: user.email },
            process.env.JWT_SECRET || 'lumina_secret_key_2025',
            { expiresIn: '8h' }
        );

        // Prepare user object for frontend
        const userResponse = { 
            ...user,
            role: user.role_name // Map role_name to role for frontend compatibility
        };
        delete userResponse.password;
        delete userResponse.role_name;

        // Ensure permissions is an object if it came as a string
        if (typeof userResponse.permissions === 'string') {
            try {
                userResponse.permissions = JSON.parse(userResponse.permissions);
            } catch (e) {
                userResponse.permissions = {};
            }
        }

        res.json({
            success: true,
            token,
            user: userResponse
        });
    } catch (err) {
        console.error('Login error:', err);
        res.status(500).json({ success: false, message: 'Server error during authentication.' });
    }
};

exports.me = async (req, res) => {
