import { useCrm } from './useCrm';
import { ModuleName, PermissionAction } from '../types';

export const usePermissions = () => {
    const { currentUser } = useCrm();

    const can = (module: ModuleName, action: PermissionAction): boolean => {
        if (!currentUser) {
            return false;
        }

        const roleName = currentUser.role;
        // Use permissions directly from the user object (injected during login/me call)
        const permissions = (currentUser as any).permissions;

        // Admins and Super Admins can do anything
        if (['Admin', 'Super Admin'].includes(roleName)) {
            return true;
        }

        if (!permissions) {
            return false;
        }

        // Handle both object and string formats (just in case)
        const activePermissions = typeof permissions === 'string' ? JSON.parse(permissions) : permissions;
        const modulePermissions = activePermissions[module];

        if (!modulePermissions) {
            return false;
        }

        return modulePermissions.includes(action);
    };

    return { can };
};

