  updateQuote: (quote: Quote) => Promise<void>;

  updateCompanyDetails: (details: CompanyDetails) => Promise<void>;
  updateEmailApiCredentials: (creds: EmailApiCredentials) => Promise<void>;
  updateMobileApiCredentials: (creds: MobileApiCredentials) => Promise<void>;

  addSaleBy: (data: Omit<SaleBy, 'id'>) => Promise<void>;
  updateSaleBy: (data: SaleBy) => Promise<void>;
  deleteSaleBy: (id: string | number) => Promise<void>;
  addWorkedBy: (data: Omit<WorkedBy, 'id'>) => Promise<void>;
  updateWorkedBy: (data: WorkedBy) => Promise<void>;
  deleteWorkedBy: (id: string | number) => Promise<void>;

  markNotificationAsRead: (id: string | number) => Promise<void>;
  getUnreadNotificationCount: () => number;

  addAnnouncement: (data: any) => Promise<void>;

  openWorkflowModal: (rule: WorkflowRule | null) => void;
  closeWorkflowModal: () => void;
  addWorkflowRule: (rule: Omit<WorkflowRule, 'id'>) => Promise<void>;
  updateWorkflowRule: (rule: WorkflowRule) => Promise<void>;
  deleteWorkflowRule: (id: string | number) => Promise<void>;

  addPermissionCategory: (cat: Omit<PermissionCategory, 'id'>) => Promise<void>;
  updatePermissionCategory: (cat: PermissionCategory) => Promise<void>;
  deletePermissionCategory: (id: string | number) => Promise<void>;
  addPermissionSection: (sec: Omit<PermissionSection, 'id'>) => Promise<void>;
  updatePermissionSection: (sec: PermissionSection) => Promise<void>;
  deletePermissionSection: (id: string | number) => Promise<void>;

  importLeads: (file: File, defaults: any) => Promise<void>;
  deleteImportedLeadFile: (id: string | number) => Promise<void>;
  addTarget: (target: Omit<Target, 'id' | 'userName' | 'achieveAmount' | 'status'>) => Promise<void>;

  addLeadStatus: (name: string) => Promise<void>;
  updateLeadStatus: (item: LeadStatus) => Promise<void>;
  deleteLeadStatus: (id: string | number) => Promise<void>;
  addApplicationStatus: (name: string) => Promise<void>;
  updateApplicationStatus: (item: ApplicationStatusItem) => Promise<void>;
  deleteApplicationStatus: (id: string | number) => Promise<void>;
  addPassportStatus: (name: string) => Promise<void>;
  updatePassportStatus: (item: PassportStatusItem) => Promise<void>;
  deletePassportStatus: (id: string | number) => Promise<void>;
  addDocumentType: (name: string) => Promise<void>;
  updateDocumentType: (item: DocumentType) => Promise<void>;
  deleteDocumentType: (id: string | number) => Promise<void>;
  addRemarkStatus: (name: string) => Promise<void>;
  updateRemarkStatus: (item: RemarkStatus) => Promise<void>;
  deleteRemarkStatus: (id: string | number) => Promise<void>;
  addLeadSource: (name: string) => Promise<void>;
  updateLeadSource: (item: LeadSource) => Promise<void>;
  deleteLeadSource: (id: string | number) => Promise<void>;
  addServiceType: (name: string) => Promise<void>;
  updateServiceType: (item: ServiceType) => Promise<void>;
  deleteServiceType: (id: string | number) => Promise<void>;
  addLostReason: (name: string) => Promise<void>;
  updateLostReason: (item: LostReason) => Promise<void>;
  deleteLostReason: (id: string | number) => Promise<void>;

  getEmailsForLead: (leadId: string | number) => Email[];
  sendEmail: (data: any) => Promise<void>;
  getWhatsAppMessagesForLead: (leadId: string | number) => WhatsAppMessage[];
  sendWhatsAppMessage: (leadId: string | number, content: string) => Promise<void>;
}

export const CrmContext = createContext<CrmContextType | undefined>(undefined);

export const CrmProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('crm_currentUser');
    return saved ? JSON.parse(saved) : null;
  });

  const [isLoading, setIsLoading] = useState(true);
  const [users, setUsers] = useState<User[]>([]);
  const [leads, setLeads] = useState<Lead[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [roles, setRoles] = useState<Role[]>([]);
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [leadNotes, setLeadNotes] = useState<LeadNote[]>([]);
  const [leadReminders, setLeadReminders] = useState<LeadReminder[]>([]);
  const [companyDetails, setCompanyDetails] = useState<CompanyDetails>(MockData.mockCompanyDetails);
  const [messages, setMessages] = useState<ChatMessage[]>([]);

  const [leadStatuses, setLeadStatuses] = useState<LeadStatus[]>([]);
  const [leadSources, setLeadSources] = useState<LeadSource[]>([]);
  const [applicationStatuses, setApplicationStatuses] = useState<ApplicationStatusItem[]>([]);
  const [passportStatuses, setPassportStatuses] = useState<PassportStatusItem[]>([]);
  const [documentTypes, setDocumentTypes] = useState<DocumentType[]>([]);
  const [remarkStatuses, setRemarkStatuses] = useState<RemarkStatus[]>([]);
  const [serviceTypes, setServiceTypes] = useState<ServiceType[]>([]);
  const [lostReasons, setLostReasons] = useState<LostReason[]>([]);
  const [saleBy, setSaleBy] = useState<SaleBy[]>([]);
  const [workedBy, setWorkedBy] = useState<WorkedBy[]>([]);

  const [isLeadModalOpen, setIsLeadModalOpen] = useState(false);
  const [editingLead, setEditingLead] = useState<Lead | null>(null);
  const [isInvoiceModalOpen, setIsInvoiceModalOpen] = useState(false);
  const [editingInvoice, setEditingInvoice] = useState<Invoice | null>(null);
  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [isRoleModalOpen, setIsRoleModalOpen] = useState(false);
  const [editingRole, setEditingRole] = useState<Role | null>(null);
  const [isVendorModalOpen, setIsVendorModalOpen] = useState(false);
  const [editingVendor, setEditingVendor] = useState<Vendor | null>(null);
  const [isQuoteBuilderOpen, setIsQuoteBuilderOpen] = useState(false);
  const [editingQuote, setEditingQuote] = useState<Quote | null>(null);
  const [currentLeadIdForQuote, setCurrentLeadIdForQuote] = useState<string | null>(null);

  const [systemLogs, setSystemLogs] = useState<SystemLog[]>([]);
  const [userActivityLogs, setUserActivityLogs] = useState<UserActivityLog[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [announcements, setAnnouncements] = useState<Announcement[]>([]);
  const [workflowRules, setWorkflowRules] = useState<WorkflowRule[]>([]);
  const [isWorkflowModalOpen, setIsWorkflowModalOpen] = useState(false);
  const [editingWorkflow, setEditingWorkflow] = useState<WorkflowRule | null>(null);
  const [permissionCategories, setPermissionCategories] = useState<PermissionCategory[]>([]);
  const [permissionSections, setPermissionSections] = useState<PermissionSection[]>([]);
  const [importedLeadFiles, setImportedLeadFiles] = useState<ImportedFile[]>([]);
  const [importedContactFiles, setImportedContactFiles] = useState<ImportedFile[]>([]);
  const [targets, setTargets] = useState<Target[]>([]);
  const [emailApiCredentials, setEmailApiCredentials] = useState<EmailApiCredentials>(MockData.mockEmailApiCredentials);
  const [mobileApiCredentials, setMobileApiCredentials] = useState<MobileApiCredentials>(MockData.mockMobileApiCredentials);
  const [quotes, setQuotes] = useState<Quote[]>([]);
  const [emails, setEmails] = useState<Email[]>([]);
  const [whatsappMessages, setWhatsappMessages] = useState<WhatsAppMessage[]>([]);

  const fetchData = useCallback(async () => {
    if (!localStorage.getItem('crm_token')) return;

    setIsLoading(true);
    try {
      const [leadsData, customersData, invoicesData, configData, targetData, logData, notificationData] = await Promise.all([
        api.leads.getAll(),
        api.customers.getAll(),
        api.invoices.getAll(),
        api.config.init(),
        api.targets.getAll(),
        api.logs.getSystem(),
        api.notifications.getAll() // Fetch real notifications
      ]);

      setLeads(leadsData);
      setCustomers(customersData);
      setInvoices(invoicesData);
      setUsers(configData.users);
      setRoles(configData.roles);
      setVendors(configData.vendors);
      setLeadSources(configData.leadSources);
      setLeadStatuses(configData.leadStatuses);
      setApplicationStatuses(configData.applicationStatuses);
      setPassportStatuses(configData.passportStatuses);
      setDocumentTypes(configData.documentTypes);
      setRemarkStatuses(configData.remarkStatuses || []);
      setServiceTypes(configData.serviceTypes || []);
      setLostReasons(configData.lostReasons || []);
      setSaleBy(configData.saleBy || []);
      setWorkedBy(configData.workedBy || []);
      setTargets(targetData);
      setSystemLogs(logData);
      setNotifications(notificationData);

      if (configData.companyDetails) setCompanyDetails(configData.companyDetails);

      // Fallback for non-critical mock data
      setAnnouncements(MockData.mockAnnouncements);
      setWorkflowRules(MockData.mockWorkflowRules);
      setPermissionCategories(MockData.mockPermissionCategories);
      setPermissionSections(MockData.mockPermissionSections);
      setImportedLeadFiles(MockData.mockImportedLeadFiles);

    } catch (err) {
      console.error('Initial data handshake failed:', err);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => { 
    if (currentUser) fetchData(); 
  }, [currentUser, fetchData]);

  const login = async (email: string, password?: string) => {
    try {
        const res = await api.auth.login({ email, password });
        if (res.success && res.token) {
            localStorage.setItem('crm_token', res.token);
            localStorage.setItem('crm_currentUser', JSON.stringify(res.user));
            setCurrentUser(res.user);
            return true;
        }
        return false;
    } catch (err) { return false; }
  };

  const logout = () => {
    localStorage.removeItem('crm_token');
    localStorage.removeItem('crm_currentUser');
    setCurrentUser(null);
  };

  // --- Actions ---
  const openLeadModal = (lead: Lead | null) => { setEditingLead(lead); setIsLeadModalOpen(true); };
  const closeLeadModal = () => setIsLeadModalOpen(false);

  const addLead = async (data: any) => { await api.leads.create(data); await fetchData(); };
  const updateLead = async (data: Lead) => { await api.leads.update(data.id, data); await fetchData(); };
  const bulkAssignLeads = async (ids: any[], userId: any) => { await api.leads.bulkAssign(ids, userId); await fetchData(); };
  const bulkDeleteLeads = async (ids: any[]) => { await api.leads.bulkDelete(ids); await fetchData(); };
  const bulkUpdateLeadStatus = async (ids: any[], status: string) => { await api.leads.bulkStatus(ids, status); await fetchData(); };
  const convertLeadToCustomer = async (lead: Lead) => { 
    await api.leads.convert(lead.id, {
        customerIdString: `CUST-${Date.now()}`,
        saleById: currentUser?.id || lead.assignedToId,
        closeDate: new Date().toISOString().split('T')[0]
    });
    await fetchData();
  };

  const addCustomer = async (data: any) => { await api.customers.create(data); await fetchData(); };
  const updateCustomer = async (data: Customer) => { await api.customers.update(data.id, data); await fetchData(); };
  const deleteCustomer = async (id: any) => { await api.customers.delete(id); await fetchData(); };

  const addInvoice = async (data: any) => { await api.invoices.create(data); await fetchData(); };
  const updateInvoice = async (data: Invoice) => { await api.invoices.update(data.id, data); await fetchData(); };
  const deleteInvoice = async (id: any) => { await api.invoices.delete(id); await fetchData(); };

  const addUser = async (data: any) => { await api.users.create(data); await fetchData(); };
  const updateUser = async (data: User) => { await api.users.update(data.id, data); await fetchData(); };
  const deleteUser = async (id: any) => { await api.users.delete(id); await fetchData(); };
  const updateProfile = async (userId: any, data: any) => { 
    await api.users.update(userId, data); 
    if (String(userId) === String(currentUser?.id)) setCurrentUser(prev => prev ? {...prev, ...data} : null); 
    await fetchData(); 
  };
  const getUserActivityLogs = (userId: any) => userActivityLogs.filter(l => String(l.userId) === String(userId));

  const getNotesForLead = (leadId: string | number) => leadNotes.filter(n => String(n.leadId) === String(leadId));
  const addNoteForLead = async (leadId: any, content: string) => {
    if (!currentUser) return;
    await api.leads.addNote(leadId, { content, author: currentUser.name });
    const notes = await api.leads.getNotes(leadId);
    setLeadNotes(prev => [...prev.filter(n => String(n.leadId) !== String(leadId)), ...notes]);
  };
  const updateNote = async (id: any, content: string) => {
    const note = leadNotes.find(n => String(n.id) === String(id));
    if(!note) return;
    await api.leads.updateNote(note.leadId, id, { content });
    const notes = await api.leads.getNotes(note.leadId);
    setLeadNotes(prev => [...prev.filter(n => String(n.leadId) !== String(note.leadId)), ...notes]);
  }; 
  const deleteNote = async (id: any) => {
    const note = leadNotes.find(n => String(n.id) === String(id));
    if(!note) return;
    await api.leads.deleteNote(note.leadId, id);
    setLeadNotes(prev => prev.filter(n => String(n.id) !== String(id)));
  };

  const getRemindersForLead = (leadId: string | number) => leadReminders.filter(r => String(r.leadId) === String(leadId));
  const addReminderForLead = async (leadId: any, note: string, dueDate: string) => {
    await api.leads.addReminder(leadId, { note, dueDate });
    const reminders = await api.leads.getReminders(leadId);
    setLeadReminders(prev => [...prev.filter(r => String(r.leadId) !== String(leadId)), ...reminders]);
  };
  const updateReminder = async (id: any, note: string, dueDate: string) => {
    const rem = leadReminders.find(r => String(r.id) === String(id));
    if(!rem) return;
    await api.leads.updateReminder(rem.leadId, id, { note, dueDate });
    const reminders = await api.leads.getReminders(rem.leadId);
    setLeadReminders(prev => [...prev.filter(r => String(r.leadId) !== String(rem.leadId)), ...reminders]);
  };
  const deleteReminder = async (id: any) => {
    const rem = leadReminders.find(r => String(r.id) === String(id));
    if(!rem) return;
    await api.leads.deleteReminder(rem.leadId, id);
    setLeadReminders(prev => prev.filter(r => String(r.id) !== String(id)));
  };
  const toggleReminderCompletion = async (id: any) => {
    await api.leads.toggleReminder(id);
    setLeadReminders(prev => prev.map(r => String(r.id) === String(id) ? { ...r, isCompleted: !r.isCompleted } : r));
  };

  const sendMessage = async (receiverId: any, content: string) => {
    if (!currentUser) return;
    await api.chat.sendMessage({ senderId: currentUser.id, receiverId, content });
    setMessages(prev => [...prev, { id: uuidv4(), senderId: currentUser.id, receiverId, content, timestamp: new Date().toISOString(), isRead: false }]);
  };

