const db = require('../db');

/**
 * Fetch all leads ordered by most recent with aliased columns
 */
exports.getAllLeads = async (req, res) => {
    try {
        const sql = `
            SELECT 
                id, 
                name, 
                phone, 
                email, 
                service, 
                country, 
                lead_source AS leadSource, 
                lead_status AS leadStatus, 
                application_status AS applicationStatus, 
                passport_status AS passportStatus, 
                company_name AS companyName, 
                location, 
                assigned_to_id AS assignedToId, 
                last_activity_at AS lastActivityAt, 
                created_at AS createdAt 
            FROM leads 
            ORDER BY created_at DESC
        `;
        const [rows] = await db.execute(sql);
        res.json(rows);
    } catch (err) { 
        console.error('Error fetching leads:', err);
        res.status(500).json({ error: 'Internal Server Error' }); 
    }
};

/**
 * Create a new lead
 */
exports.createLead = async (req, res) => {
    let {
        name = '',
        phone = '',
        email = null,
        service = null,
        country = null,
        leadSource = null,
        leadStatus = 'New Lead',
        applicationStatus = null,
        passportStatus = 'With Client',
        companyName = null,
        location = null,
        assignedToId = null
    } = req.body;

    // Sanitize Foreign Keys: convert empty strings to null
    if (assignedToId === '') assignedToId = null;

    const sql = `INSERT INTO leads (name, phone, email, service, country, lead_source, lead_status, application_status, passport_status, company_name, location, assigned_to_id) 
                 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`;
    try {
        const [result] = await db.execute(sql, [name, phone, email, service, country, leadSource, leadStatus, applicationStatus, passportStatus, companyName, location, assignedToId]);
        res.json({ success: true, id: result.insertId });
    } catch (err) { 
        console.error('Error creating lead:', err);
        res.status(500).json({ error: err.message }); 
    }
};

