exports.getReminders = async (req, res) => {
    try {
        const [rows] = await db.execute('SELECT id, lead_id AS leadId, note, due_date AS dueDate, is_completed AS isCompleted FROM lead_reminders WHERE lead_id = ? ORDER BY due_date ASC', [req.params.id]);
        res.json(rows);
    } catch (err) { res.status(500).json({ error: err.message }); }
};

exports.addReminder = async (req, res) => {
    const { note = '', dueDate = null } = req.body;
    try {
        const [result] = await db.execute('INSERT INTO lead_reminders (lead_id, note, due_date) VALUES (?, ?, ?)', [req.params.id, note, dueDate]);
        res.json({ success: true, id: result.insertId });
    } catch (err) { res.status(500).json({ error: err.message }); }
};

exports.updateReminder = async (req, res) => {
    const { note = '', dueDate = null } = req.body;
    try {
        await db.execute('UPDATE lead_reminders SET note = ?, due_date = ? WHERE id = ?', [note, dueDate, req.params.reminderId]);
        res.json({ success: true });
    } catch (err) { res.status(500).json({ error: err.message }); }
};

exports.deleteReminder = async (req, res) => {
    try {
        await db.execute('DELETE FROM lead_reminders WHERE id = ?', [req.params.reminderId]);
        res.json({ success: true });
    } catch (err) { res.status(500).json({ error: err.message }); }
};

exports.toggleReminder = async (req, res) => {
    try {
        await db.execute('UPDATE lead_reminders SET is_completed = NOT is_completed WHERE id = ?', [req.params.id]);
        res.json({ success: true });
    } catch (err) { res.status(500).json({ error: err.message }); }
};

const express = require('express');
const router = express.Router();
const leadController = require('../controllers/leadController');

router.get('/', leadController.getAllLeads);
router.post('/', leadController.createLead);
router.put('/:id', leadController.updateLead);
router.delete('/:id', leadController.deleteLead);

// Bulk Operations
router.post('/bulk-assign', leadController.bulkAssign);
router.post('/bulk-status', leadController.bulkStatus);
router.post('/bulk-delete', leadController.bulkDelete);

// Special Operations
router.post('/convert/:id', leadController.convertToCustomer);

// Activity (Notes)
router.get('/:id/notes', leadController.getNotes);
router.post('/:id/notes', leadController.addNote);
router.put('/:id/notes/:noteId', leadController.updateNote);
router.delete('/:id/notes/:noteId', leadController.deleteNote);

// Activity (Reminders)
router.get('/:id/reminders', leadController.getReminders);
router.post('/:id/reminders', leadController.addReminder);
router.put('/:id/reminders/:reminderId', leadController.updateReminder);
router.delete('/:id/reminders/:reminderId', leadController.deleteReminder);
router.put('/reminders/:id/toggle', leadController.toggleReminder);

module.exports = router;

