/**
 * Fetch all leads ordered by most recent with aliased columns
 */
exports.getAllLeads = async (req, res) => {
    try {
        const sql = `
            SELECT 
                id, 
                name, 
                phone, 
                email, 
                service, 
                country, 
                lead_source AS leadSource, 
                lead_status AS leadStatus, 
                application_status AS applicationStatus, 
                passport_status AS passportStatus, 
                company_name AS companyName, 
                location, 
                assigned_to_id AS assignedToId, 
                last_activity_at AS lastActivityAt, 
