/**
 * Professional conversion of Lead to Customer within a managed transaction
 */
exports.convertToCustomer = async (req, res) => {
    const { id } = req.params;
    let { customerIdString, saleById, closeDate } = req.body;
    const connection = await db.getConnection();
    try {
        await connection.beginTransaction();

        const [[lead]] = await connection.execute('SELECT * FROM leads WHERE id = ?', [id]);
        if (!lead) throw new Error('Lead not found');

        // Sanitize Foreign Keys
        if (saleById === '') saleById = null;

        // Insert into customers table using lead metadata
        const sql = `INSERT INTO customers (customer_id_string, name, phone, email, country, company_name, location, sale_by_id, close_date, passport_status, service_type) 
                     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`;
        await connection.execute(sql, [
            customerIdString || null, 
            lead.name, 
            lead.phone, 
            lead.email, 
            lead.country, 
            lead.company_name, 
            lead.location, 
            saleById || null, 
            closeDate || null, 
            lead.passport_status,
            lead.service
        ]);

        // Mark lead as "Won"
        await connection.execute('UPDATE leads SET lead_status = "Won", last_activity_at = CURRENT_TIMESTAMP WHERE id = ?', [id]);

        await connection.commit();
        res.json({ success: true });
    } catch (err) {
        await connection.rollback();
        console.error('Transaction rollback in convertToCustomer:', err);
        res.status(500).json({ error: err.message });
    } finally { 
        connection.release(); 
    }
};

