/**
 * Fetch all leads ordered by most recent with aliased columns and activity counts
 */
exports.getAllLeads = async (req, res) => {
    try {
        const sql = `
            SELECT 
                l.id, 
                l.name, 
                l.phone, 
                l.email, 
                l.service, 
                l.country, 
                l.lead_source AS leadSource, 
                l.lead_status AS leadStatus, 
                l.application_status AS applicationStatus, 
                l.passport_status AS passportStatus, 
                l.company_name AS companyName, 
                l.location, 
                l.assigned_to_id AS assignedToId, 
                l.last_activity_at AS lastActivityAt, 
                l.created_at AS createdAt,
                (SELECT COUNT(*) FROM lead_notes WHERE lead_id = l.id) AS notesCount,
                (SELECT COUNT(*) FROM lead_reminders WHERE lead_id = l.id AND is_completed = 0) AS remindersCount,
                (SELECT content FROM lead_notes WHERE lead_id = l.id ORDER BY created_at DESC LIMIT 1) AS latestNote
            FROM leads l
            ORDER BY l.created_at DESC
        `;
        const [rows] = await db.execute(sql);
        res.json(rows);
    } catch (err) { 
        console.error('Error fetching leads:', err);
        res.status(500).json({ error: 'Internal Server Error' }); 
    }
};

