const ImportDataContent: React.FC = () => {
    const { users, leadStatuses, leadSources, importLeads } = useCrm();
    const [fileName, setFileName] = useState('');
    const fileInputRef = useRef<HTMLInputElement>(null);
    const [file, setFile] = useState<File | null>(null);
    const [defaults, setDefaults] = useState({
        assignedToId: String(users[0]?.id || ''),
        leadStatus: leadStatuses[0]?.name || '',
        leadSource: String(leadSources[0]?.name || ''),
        note: ''
    });

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            setFile(e.target.files[0]);
            setFileName(e.target.files[0].name);
        } else {
            setFile(null);
            setFileName('');
        }
    };

    const handleDefaultsChange = (e: React.ChangeEvent<HTMLSelectElement | HTMLInputElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setDefaults(prev => ({ ...prev, [name]: value }));
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (file) {
            importLeads(file, defaults);
            setFile(null);
            setFileName('');
        }
    };

    return (
        <div>
            <h3 className="text-xl font-semibold mb-6 border-b pb-3">Import Data</h3>
            <form className="space-y-6" onSubmit={handleSubmit}>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                        <label className="block text-sm font-medium text-gray-700">Select Module Type</label>
                        <select className="mt-1 input-field" required>
                            <option value="">Select Module</option>
                            <option value="Lead">Leads</option>
                            <option value="Contact">Contacts</option>
                        </select>
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700">Select User</label>
                        <select name="assignedToId" value={defaults.assignedToId} onChange={handleDefaultsChange} className="mt-1 input-field">
                            <option value="">Select User</option>
                            {users.map(user => <option key={user.id} value={String(user.id)}>{capitalizeName(user.name)}</option>)}
                        </select>
                    </div>
                     <div>
                        <label className="block text-sm font-medium text-gray-700">Upload File</label>
                        <div className="mt-1 relative">
                            <input type="file" ref={fileInputRef} onChange={handleFileChange} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" accept=".csv" />
                            <div className="flex items-center justify-between border border-gray-300 rounded-md p-2 bg-white">
                                <span className="text-gray-500 truncate">{fileName || 'Choose file'}</span>
                                <button type="button" onClick={() => fileInputRef.current?.click()} className="px-3 py-1 bg-gray-100 text-sm font-medium rounded-md hover:bg-gray-200">Browse</button>
                            </div>
                        </div>
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700">Status</label>
                        <select name="leadStatus" value={defaults.leadStatus} onChange={handleDefaultsChange} className="mt-1 input-field">
                            <option value="">Select Status</option>
                            {leadStatuses.map(status => <option key={status.id} value={status.name}>{status.name}</option>)}
                        </select>
                    </div>
                    <div className="md:col-span-2">
                        <label className="block text-sm font-medium text-gray-700">Source</label>
                        <select name="leadSource" value={defaults.leadSource} onChange={handleDefaultsChange} className="mt-1 input-field">
                            <option value="">Lead Source</option>
                            {leadSources.map(source => <option key={source.id} value={source.name}>{source.name}</option>)}
                        </select>
                    </div>
                    <div className="md:col-span-2">
                        <label className="block text-sm font-medium text-gray-700">Add Note (Optional)</label>
                        <textarea name="note" value={defaults.note} onChange={handleDefaultsChange} rows={3} className="mt-1 input-field" placeholder="This note will be added to all imported leads..."></textarea>
                    </div>
                </div>
                <div className="pt-4 border-t">
                    <button type="submit" className="px-5 py-2 bg-primary text-white font-semibold rounded-lg hover:bg-primary/90 text-sm">
                        Submit
                    </button>
                </div>
            </form>
        </div>
    );
};

interface ImportedListViewContentProps { type: 'Lead' | 'Contact'; }
const ImportedListViewContent: React.FC<ImportedListViewContentProps> = ({ type }) => {
    const { importedLeadFiles, importedContactFiles, deleteImportedLeadFile } = useCrm();
    const { fireToast, confirmDelete } = useSwal();
    const [searchTerm, setSearchTerm] = useState('');

    const items = type === 'Lead' ? importedLeadFiles : importedContactFiles;

    const { items: sortedItems, requestSort, sortConfig } = useSorting<ImportedFile>(items, { key: 'createdAt', direction: 'descending'});

    const filteredItems = useMemo(() => {
        return sortedItems.filter(item => item.fileName.toLowerCase().includes(searchTerm.toLowerCase()));
    }, [sortedItems, searchTerm]);

    const {
        paginatedData,
        currentPage,
        setCurrentPage,
        totalPages,
        itemsPerPage,
        setItemsPerPage,
        startIndex,
        endIndex,
        totalItems
    } = usePagination(filteredItems, 10);

    const handleDelete = async (file: ImportedFile) => {
        const result = await confirmDelete({
            title: 'Delete Import Record?',
            html: `Are you sure you want to delete history for "${file.fileName}"?`
        });
        if (result) {
            deleteImportedLeadFile(String(file.id));
            fireToast('success', 'Record deleted');
        }
    };

    return (
        <div className="space-y-4">
             <div className="flex justify-between items-center">
                <h3 className="text-xl font-semibold">{type} Imported List</h3>
                <SearchInput value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-64" />
            </div>
            <div className="overflow-x-auto border rounded-lg">
                <table className="w-full text-sm">
                    <thead className="bg-gray-50">
                        <tr>
                            <th className="p-3 text-left font-semibold text-gray-600">S.No</th>
                            <th className="p-3 text-left font-semibold text-gray-600">File Name</th>
                            <th className="p-3 text-left font-semibold text-gray-600">Total Records</th>
                            <th className="p-3 text-left font-semibold text-gray-600">Added By</th>
                            <th className="p-3 text-left font-semibold text-gray-600 cursor-pointer" onClick={() => requestSort('createdAt')}>
                                Date {sortConfig?.key === 'createdAt' && (sortConfig.direction === 'ascending' ? '↑' : '↓')}
                            </th>
                            <th className="p-3 text-left font-semibold text-gray-600">Action</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y">
                        {paginatedData.map((item, i) => (
                            <tr key={item.id}>
                                <td className="p-3">{startIndex + i}</td>
                                <td className="p-3">{item.fileName}</td>
                                <td className="p-3 font-bold text-primary">{item.totalLeads}</td>
                                <td className="p-3">{item.addedBy}</td>
                                <td className="p-3">{new Date(item.createdAt).toLocaleDateString()}</td>
                                <td className="p-3">
                                    <button onClick={() => handleDelete(item)} className="text-red-500 hover:bg-red-50 p-2 rounded-full transition-colors">
                                        <i className="ri-delete-bin-line"></i>
                                    </button>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
            <Pagination {...{currentPage, totalPages, onPageChange: setCurrentPage, itemsPerPage, onItemsPerPageChange: setItemsPerPage, totalItems, startIndex, endIndex}} />
        </div>
    );
};

const SetTargetsContent: React.FC = () => {
    const { users, targets, addTarget, deleteTarget } = useCrm();
    const { fireToast, confirmDelete } = useSwal();
    const [formData, setFormData] = useState({
        userId: '',
        targetAmount: 0,
        module: 'Lead' as 'Lead' | 'Sales'
    });

    // Ensure we have a default userId when users load
    useEffect(() => {
        if (users.length > 0 && !formData.userId) {
            setFormData(prev => ({ ...prev, userId: String(users[0].id) }));
        }
    }, [users, formData.userId]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!formData.userId) return;

        try {
            await addTarget({
                userId: formData.userId,
                targetAmount: formData.targetAmount,
                module: formData.module
            });
            fireToast('success', 'Target assigned successfully');
            setFormData(prev => ({ ...prev, targetAmount: 0 }));
        } catch (err) {
            fireToast('error', 'Failed to set target');
        }
    };

    const handleDelete = async (target: Target) => {
        const result = await confirmDelete({
            title: 'Remove Target?',
            html: `Are you sure you want to remove target for <strong>${target.userName}</strong>?`
        });
        if (result) {
            try {
                await deleteTarget(String(target.id));
                fireToast('success', 'Target removed');
            } catch (err) {
                fireToast('error', 'Failed to remove target');
            }
        }
    };

    return (
        <div className="space-y-8">
            <div className="bg-gray-50 p-6 rounded-lg border">
                <h3 className="text-lg font-bold mb-4">Set New Target</h3>
                <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-4 gap-4 items-end">
                    <div>
                        <label className="block text-sm font-medium mb-1 text-gray-600">Select Agent</label>
                        <select value={formData.userId} onChange={e => setFormData({...formData, userId: e.target.value})} className="input-field" required>
                            <option value="" disabled>Select Agent</option>
                            {users.map(u => <option key={u.id} value={String(u.id)}>{capitalizeName(u.name)}</option>)}
                        </select>
                    </div>
                    <div>
                        <label className="block text-sm font-medium mb-1 text-gray-600">Target Category</label>
                        <select value={formData.module} onChange={e => setFormData({...formData, module: e.target.value as any})} className="input-field">
                            <option value="Lead">Leads Generation</option>
                            <option value="Sales">Sales Revenue</option>
                        </select>
                    </div>
                    <div>
                        <label className="block text-sm font-medium mb-1 text-gray-600">Amount / Count</label>
                        <input 
                            type="number" 
                            value={formData.targetAmount || ''} 
                            onChange={e => setFormData({...formData, targetAmount: Number(e.target.value)})} 
                            className="input-field" 
                            required 
                            placeholder="e.g. 50000"
                        />
                    </div>
                    <button type="submit" className="bg-primary text-white font-bold py-2.5 rounded-lg hover:bg-primary/90 transition-all shadow-sm active:scale-95">
                        Set Target
                    </button>
                </form>
            </div>

            <div className="space-y-4">
                <h3 className="text-lg font-bold text-gray-800">Current Targets</h3>
                <div className="overflow-x-auto border rounded-lg">
                    <table className="w-full text-sm">
                        <thead className="bg-gray-100">
                            <tr>
                                <th className="p-4 text-left font-semibold text-gray-600">Agent Name</th>
                                <th className="p-4 text-left font-semibold text-gray-600">Module</th>
                                <th className="p-4 text-left font-semibold text-gray-600">Goal</th>
                                <th className="p-4 text-left font-semibold text-gray-600">Achieved</th>
                                <th className="p-4 text-left font-semibold text-gray-600 w-1/4">Progress</th>
                                <th className="p-4 text-center font-semibold text-gray-600">Action</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y bg-white">
                            {targets.map(t => {
                                const isRevenue = t.module === 'Sales';
                                const progress = t.targetAmount > 0 ? Math.min(100, (t.achieveAmount / t.targetAmount) * 100) : 0;
                                return (
                                    <tr key={t.id} className="hover:bg-gray-50 transition-colors">
                                        <td className="p-4 font-bold text-gray-800">{capitalizeName(t.userName || 'Unknown')}</td>
                                        <td className="p-4">
                                            <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold uppercase border ${t.module === 'Lead' ? 'bg-blue-50 text-blue-700 border-blue-100' : 'bg-green-50 text-green-700 border-green-100'}`}>
                                                {t.module}
                                            </span>
                                        </td>
                                        <td className="p-4 font-semibold text-gray-700">
                                            {isRevenue ? `₹${Number(t.targetAmount).toLocaleString()}` : t.targetAmount}
                                        </td>
                                        <td className="p-4 font-semibold text-green-600">
                                            {isRevenue ? `₹${Number(t.achieveAmount).toLocaleString()}` : t.achieveAmount}
                                        </td>
                                        <td className="p-4">
                                            <div className="flex items-center gap-2">
                                                <div className="flex-grow bg-gray-100 rounded-full h-2 overflow-hidden shadow-inner">
                                                    <div 
                                                        className={`h-full rounded-full transition-all duration-1000 ${progress >= 100 ? 'bg-green-500' : progress > 50 ? 'bg-amber-500' : 'bg-primary'}`} 
                                                        style={{width: `${progress}%`}}
                                                    ></div>
                                                </div>
                                                <span className="text-[10px] font-bold text-gray-500 min-w-[30px]">{Math.round(progress)}%</span>
                                            </div>
                                        </td>
                                        <td className="p-4 text-center">
                                            <button 
                                                onClick={() => handleDelete(t)}
                                                className="w-8 h-8 flex items-center justify-center rounded-full text-gray-400 hover:text-red-600 hover:bg-red-50 transition-colors"
                                                title="Delete Target"
                                            >
                                                <i className="ri-delete-bin-line text-lg"></i>
                                            </button>
                                        </td>
                                    </tr>
                                );
                            })}
                            {targets.length === 0 && (
                                <tr>
                                    <td colSpan={6} className="text-center py-10 text-gray-500 italic bg-white">
                                        No active targets found. Set a goal to start tracking performance.
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

