        const sql = `
            SELECT 
                l.id, l.name, l.phone, l.email, l.service, l.country, 
                l.lead_source AS leadSource, l.lead_status AS leadStatus, 
                l.application_status AS applicationStatus, l.passport_status AS passportStatus, 
