const db = require('../db');
const { logAction } = require('../utils/logger');

exports.getAllLeads = async (req, res) => {
    try {
        const sql = `
            SELECT 
                l.id, l.name, l.phone, l.email, l.service, l.country, 
                l.lead_source AS leadSource, l.lead_status AS leadStatus, 
                l.application_status AS applicationStatus, l.passport_status AS passportStatus, 
                l.company_name AS companyName, l.location, l.assigned_to_id AS assignedToId, 
                l.last_activity_at AS lastActivityAt, l.created_at AS createdAt,
                (SELECT COUNT(*) FROM lead_notes WHERE lead_id = l.id) AS notesCount,
                (SELECT COUNT(*) FROM lead_reminders WHERE lead_id = l.id AND is_completed = 0) AS remindersCount,
                (SELECT content FROM lead_notes WHERE lead_id = l.id ORDER BY created_at DESC LIMIT 1) AS latestNote
            FROM leads l
            ORDER BY l.created_at DESC
        `;
        const [rows] = await db.execute(sql);
        res.json(rows);
    } catch (err) { 
        res.status(500).json({ error: 'Internal Server Error' }); 
    }
};

exports.createLead = async (req, res) => {
    const p = req.body;

    // Explicitly handle potentially undefined values by defaulting to null
    const name = p.name ?? '';
    const phone = p.phone ?? '';
    const email = p.email ?? null;
    const service = p.service ?? null;
    const country = p.country ?? null;
    const leadSource = p.leadSource ?? null;
    const leadStatus = p.leadStatus ?? 'New Lead';
    const applicationStatus = p.applicationStatus ?? null;
    const passportStatus = p.passportStatus ?? 'With Client';
    const companyName = p.companyName ?? null;
    const location = p.location ?? null;
    const assignedToId = (p.assignedToId === '' || p.assignedToId === undefined) ? null : p.assignedToId;

    try {
        const [result] = await db.execute(
            `INSERT INTO leads (name, phone, email, service, country, lead_source, lead_status, application_status, passport_status, company_name, location, assigned_to_id) 
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
            [name, phone, email, service, country, leadSource, leadStatus, applicationStatus, passportStatus, companyName, location, assignedToId]
        );

        await logAction(req.user.id, req.user.name, req.user.role, `Created new lead: ${name}`);
        res.json({ success: true, id: result.insertId });
    } catch (err) { 
        console.error('Lead creation DB error:', err);
        res.status(500).json({ error: err.message }); 
    }
};

exports.updateLead = async (req, res) => {
    const { id } = req.params;
    const p = req.body;

    const name = p.name ?? '';
    const phone = p.phone ?? '';
    const email = p.email ?? null;
    const service = p.service ?? null;
    const country = p.country ?? null;
    const leadSource = p.leadSource ?? null;
    const leadStatus = p.leadStatus ?? 'New Lead';
    const applicationStatus = p.applicationStatus ?? null;
    const passportStatus = p.passportStatus ?? 'With Client';
    const companyName = p.companyName ?? null;
    const location = p.location ?? null;
    const assignedToId = (p.assignedToId === '' || p.assignedToId === undefined) ? null : p.assignedToId;

    try {
        await db.execute(
            `UPDATE leads SET name=?, phone=?, email=?, service=?, country=?, lead_source=?, lead_status=?, application_status=?, passport_status=?, company_name=?, location=?, assigned_to_id=?, last_activity_at=CURRENT_TIMESTAMP WHERE id=?`,
            [name, phone, email, service, country, leadSource, leadStatus, applicationStatus, passportStatus, companyName, location, assignedToId, id]
        );

        await logAction(req.user.id, req.user.name, req.user.role, `Updated lead: ${name}`);
        res.json({ success: true });
    } catch (err) { 
        res.status(500).json({ error: err.message }); 
    }
