 * Robust logging utility to record system events.
 * Handles undefined values to prevent SQL binding errors.
 */
exports.logAction = async (userId, userName, roleName, title) => {
    try {
        // mysql2/promise .execute() throws if any value is 'undefined'.
        // We use the null-coalescing operator to ensure SQL NULL is passed instead.
        const params = [
            userId ?? null,
            userName ?? null,
            roleName ?? null,
            title ?? "No description provided"
        ];

        await db.execute(
            'INSERT INTO system_logs (user_id, user_name, role_name, title) VALUES (?, ?, ?, ?)',
            params
        );
    } catch (err) {
        // We log the error but don't crash the main request - logging is secondary to the business action.
        console.error('CRITICAL: System Logging Failed:', err.message);
    }
};

const db = require('../db');
const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');

exports.login = async (req, res) => {
    const { email, password } = req.body;

    try {
        const [rows] = await db.execute(
            'SELECT u.*, r.permissions FROM users u LEFT JOIN roles r ON u.role_id = r.id WHERE (u.email = ? OR u.username = ?) AND u.status = "Active"',
            [email, email]
        );

        if (rows.length === 0) {
            return res.status(401).json({ success: false, message: 'Invalid credentials.' });
        }

        const user = rows[0];
        const isMatch = await bcrypt.compare(password, user.password).catch(() => false);

        if (!isMatch) {
            return res.status(401).json({ success: false, message: 'Invalid credentials.' });
        }

        // --- Senior Level Implementation: Record Access Log ---
        // Capture IP and Device Info for security audit
        const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
        const userAgent = req.get('User-Agent') || 'Unknown';

        // Non-blocking log insertion
        db.execute(
            'INSERT INTO user_activity_logs (user_id, ip_address, user_agent, status, location) VALUES (?, ?, ?, "Logged In", "Web Application")',
            [user.id, ip, userAgent]
        ).catch(e => console.error('Access log failed:', e));

        const token = jwt.sign(
            { id: user.id, role: user.role_name, email: user.email, name: user.name },
            process.env.JWT_SECRET || 'lumina_secret_key_2025',
            { expiresIn: '8h' }
        );

        const userResponse = { ...user, role: user.role_name };
        delete userResponse.password;
        delete userResponse.role_name;

        if (typeof userResponse.permissions === 'string') {
            try { userResponse.permissions = JSON.parse(userResponse.permissions); } catch (e) { userResponse.permissions = {}; }
        }

        res.json({ success: true, token, user: userResponse });
    } catch (err) {
        console.error('Login error:', err);
        res.status(500).json({ success: false, message: 'Server error during authentication.' });
    }
};

