exports.addDocument = async (req, res) => {
    const { name = '', status = 'Pending' } = req.body;
    try {
        const [[lead]] = await db.execute('SELECT name FROM leads WHERE id = ?', [req.params.id]);
        const [result] = await db.execute('INSERT INTO lead_documents (lead_id, name, status) VALUES (?, ?, ?)', [req.params.id, name, status]);

        await logAction(req.user.id, req.user.name, req.user.role, `Added document placeholder (${name}) for lead: ${lead?.name || 'Unknown'}`);
        res.json({ success: true, id: result.insertId });
    } catch (err) { res.status(500).json({ error: err.message }); }
};

exports.updateDocument = async (req, res) => {
    const { status, fileName, fileType, fileData, notes } = req.body;
    const { docId } = req.params;
    try {
        const [[doc]] = await db.execute('SELECT l.name, d.name as docName FROM lead_documents d JOIN leads l ON d.lead_id = l.id WHERE d.id = ?', [docId]);

        let sql = 'UPDATE lead_documents SET updated_at = CURRENT_TIMESTAMP';
        const params = [];
        if (status) { sql += ', status = ?'; params.push(status); }
        if (fileName) { sql += ', file_name = ?'; params.push(fileName); }
        if (fileType) { sql += ', file_type = ?'; params.push(fileType); }
        if (fileData) { sql += ', file_data = ?'; params.push(fileData); }
        if (notes !== undefined) { sql += ', notes = ?'; params.push(notes); }
        sql += ' WHERE id = ?';
        params.push(docId);
        await db.execute(sql, params);

        await logAction(req.user.id, req.user.name, req.user.role, `Updated document status/file for ${doc?.docName} on lead: ${doc?.name || 'Unknown'}`);
        res.json({ success: true });
    } catch (err) { res.status(500).json({ error: err.message }); }
};

exports.deleteDocument = async (req, res) => {
    try {
        const [[doc]] = await db.execute('SELECT l.name, d.name as docName FROM lead_documents d JOIN leads l ON d.lead_id = l.id WHERE d.id = ?', [req.params.docId]);
        await db.execute('DELETE FROM lead_documents WHERE id = ?', [req.params.docId]);

        await logAction(req.user.id, req.user.name, req.user.role, `Removed document ${doc?.docName} from lead: ${doc?.name || 'Unknown'}`);
        res.json({ success: true });
    } catch (err) { res.status(500).json({ error: err.message }); }
};

const db = require('../db');
const bcrypt = require('bcryptjs');
const { logAction } = require('../utils/logger');

exports.getAllUsers = async (req, res) => {
    try {
        const [rows] = await db.execute('SELECT id, name, username, email, role_name as role, status, image_url FROM users');
        res.json(rows);
    } catch (err) { res.status(500).json({ error: err.message }); }
};

exports.createUser = async (req, res) => {
    const p = req.body;
    const name = p.name ?? '';
    const username = p.username ?? '';
    const email = p.email ?? '';
    const password = p.password ?? 'password123';
    const role = p.role ?? null;
    const status = p.status ?? 'Active';
    const imageUrl = p.imageUrl ?? null;

    try {
        const salt = await bcrypt.genSalt(10);
        const hashedPassword = await bcrypt.hash(password, salt);

        const [result] = await db.execute(
            'INSERT INTO users (name, username, email, password, role_name, status, image_url) VALUES (?, ?, ?, ?, ?, ?, ?)',
            [name, username, email, hashedPassword, role, status, imageUrl]
        );

        await logAction(req.user.id, req.user.name, req.user.role, `Created user: ${name}`);
        res.json({ success: true, id: result.insertId });
    } catch (err) { res.status(500).json({ error: err.message }); }
};

exports.updateUser = async (req, res) => {
    const p = req.body;
    const name = p.name ?? '';
    const username = p.username ?? '';
    const email = p.email ?? '';
    const role = p.role ?? null;
    const status = p.status ?? 'Active';
    const imageUrl = p.imageUrl ?? null;
    const password = p.password ?? null;

    try {
        let sql = 'UPDATE users SET name=?, username=?, email=?, role_name=?, status=?, image_url=?';
        const params = [name, username, email, role, status, imageUrl];

        if (password && password.trim() !== '') {
            const salt = await bcrypt.genSalt(10);
            const hashedPassword = await bcrypt.hash(password, salt);
            sql += ', password=?';
            params.push(hashedPassword);
        }

        sql += ' WHERE id=?';
        params.push(req.params.id);

        await db.execute(sql, params);
        await logAction(req.user.id, req.user.name, req.user.role, `Updated user info: ${name}`);
        res.json({ success: true });
    } catch (err) { res.status(500).json({ error: err.message }); }
};

exports.deleteUser = async (req, res) => {
    try {
        const [[user]] = await db.execute('SELECT name FROM users WHERE id = ?', [req.params.id]);
        await db.execute('DELETE FROM users WHERE id = ?', [req.params.id]);
        if (user) {
            await logAction(req.user.id, req.user.name, req.user.role, `Deleted user: ${user.name}`);
        }
        res.json({ success: true });
    } catch (err) { res.status(500).json({ error: err.message }); }
};

exports.getAllRoles = async (req, res) => {
    try {
        const [rows] = await db.execute('SELECT * FROM roles');
        // Robust JSON parsing for permissions
        const parsedRows = rows.map(role => {
            if (typeof role.permissions === 'string') {
                try {
                    role.permissions = JSON.parse(role.permissions);
                } catch (e) {
                    role.permissions = {};
                }
            }
            return role;
        });
        res.json(parsedRows);
    } catch (err) { res.status(500).json({ error: err.message }); }
};

exports.createRole = async (req, res) => {
    const { name = '', permissions = {}, status = 'Active' } = req.body;
    try {
        const [result] = await db.execute('INSERT INTO roles (name, permissions, status) VALUES (?, ?, ?)', [name, JSON.stringify(permissions), status]);
        await logAction(req.user.id, req.user.name, req.user.role, `Security: Created new role "${name}"`);
        res.json({ success: true, id: result.insertId });
    } catch (err) { res.status(500).json({ error: err.message }); }
};

exports.updateRole = async (req, res) => {
    const { name = '', permissions = {}, status = 'Active' } = req.body;
    try {
        // Prevent accidental downgrade of Super Admin via API if possible
        if (req.params.id == 1 || name.toLowerCase() === 'super admin') {
            // Logic to ensure permissions stay full could go here, 
            // but we'll handle standard updates for now.
        }
        await db.execute('UPDATE roles SET name=?, permissions=?, status=? WHERE id=?', [name, JSON.stringify(permissions), status, req.params.id]);
        await logAction(req.user.id, req.user.name, req.user.role, `Security: Updated permissions for role "${name}"`);
        res.json({ success: true });
    } catch (err) { res.status(500).json({ error: err.message }); }
};

exports.deleteRole = async (req, res) => {
    try {
        const [[role]] = await db.execute('SELECT name FROM roles WHERE id = ?', [req.params.id]);
        if (!role) return res.status(404).json({ error: 'Role not found' });

        if (req.params.id == 1 || role.name.toLowerCase() === 'super admin') {
            return res.status(403).json({ error: 'System Protected: Super Admin role cannot be deleted.' });
        }

        await db.execute('DELETE FROM roles WHERE id = ?', [req.params.id]);
        await logAction(req.user.id, req.user.name, req.user.role, `Security: Permanently deleted role "${role.name}"`);
        res.json({ success: true });
    } catch (err) { res.status(500).json({ error: err.message }); }
};

import React from 'react';
import { useCrm } from '../../hooks/useCrm';
import { usePermissions } from '../../hooks/usePermissions';
import { useSwal } from '../../hooks/useSwal';
import { usePagination } from '../../hooks/usePagination';
import Pagination from '../common/Pagination';
import { Role } from '../../types';
import { useSorting } from '../../hooks/useSorting';
import Tooltip from '../common/Tooltip';

const RoleManagement: React.FC = () => {
  const { roles, openRoleModal, deleteRole } = useCrm();
  const permissions = usePermissions();
  const { confirmDelete, fireToast } = useSwal();

  const canCreate = permissions.can('roles', 'create');
  const canUpdate = permissions.can('roles', 'update');
  const canDelete = permissions.can('roles', 'delete');

  const { items: sortedRoles, requestSort, sortConfig } = useSorting<Role>(roles, { key: 'name', direction: 'ascending'});

  const {
    paginatedData,
    currentPage,
    setCurrentPage,
    totalPages,
    itemsPerPage,
    setItemsPerPage,
    startIndex,
    endIndex,
    totalItems
  } = usePagination(sortedRoles, 10);

  const handleDelete = async (role: Role) => {
    // Protection for Super Admin
    if (String(role.id) === '1' || role.name.toLowerCase() === 'super admin') {
        fireToast('error', 'The Super Admin role is system-protected and cannot be deleted.');
        return;
    }

    const result = await confirmDelete({
        title: 'Delete Role?',
        html: <>Are you sure you want to delete the role "<strong>{role.name}</strong>"? Users assigned to this role will lose their current permissions.</>,
    });

    if (result) {
      try {
        await deleteRole(String(role.id));
        fireToast('success', `Role "${role.name}" deleted successfully.`);
      } catch (err: any) {
        fireToast('error', err.message || 'Failed to delete role.');
      }
    }
  }

  const isSystemRole = (role: Role) => {
      return String(role.id) === '1' || role.name.toLowerCase() === 'super admin';
  };

  return (
    <div className="bg-white p-6 rounded-lg shadow-md border border-gray-200">
      <div className="flex flex-wrap gap-4 justify-between items-center mb-6">
        <div>
            <h2 className="text-2xl font-semibold text-gray-800">User Roles</h2>
            <p className="text-sm text-gray-500 mt-1">Manage system access levels and permissions grid.</p>
        </div>
        {canCreate && (
            <button onClick={() => openRoleModal(null)} className="px-4 py-2 text-sm font-medium text-white bg-primary rounded-md hover:bg-primary/90 flex items-center shadow-sm transition-all hover:shadow-md">
                <i className="ri-add-line mr-2"></i>
                Create Role
            </button>
        )}
      </div>

      <div className="overflow-x-auto rounded-lg border border-gray-100">
          <table className="w-full">
            <thead className="bg-gray-50 border-b border-gray-100">
              <tr>
                <th className="p-4 text-left text-sm font-semibold text-gray-600 cursor-pointer hover:bg-gray-100 group" onClick={() => requestSort('name')}>
                  <div className="flex items-center">Role Name {sortConfig?.key === 'name' ? (<i className={`ml-1 ${sortConfig.direction === 'ascending' ? 'ri-arrow-up-s-line' : 'ri-arrow-down-s-line'}`}></i>) : (<i className="ml-1 text-gray-400 ri-arrow-up-down-line opacity-0 group-hover:opacity-100 transition-opacity"></i>)}</div>
                </th>
                <th className="p-4 text-left text-sm font-semibold text-gray-600">Permissions Status</th>
                <th className="p-4 text-left text-sm font-semibold text-gray-600">Account Status</th>
                {(canUpdate || canDelete) && <th className="p-4 text-left text-sm font-semibold text-gray-600">Actions</th>}
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200">
              {paginatedData.map((role: Role) => {
                const isProtected = isSystemRole(role);
                const permCount = Object.keys(role.permissions || {}).length;

                return (
                    <tr key={role.id} className="hover:bg-gray-50 transition-colors">
                    <td className="p-4 whitespace-nowrap">
                        <div className="flex items-center gap-2">
                            <span className="font-bold text-gray-900">{role.name}</span>
                            {isProtected && <span className="px-2 py-0.5 text-[10px] font-bold bg-amber-100 text-amber-700 rounded uppercase tracking-wider">System Protected</span>}
                        </div>
                    </td>
                    <td className="p-4 whitespace-nowrap">
                        <span className="text-xs text-gray-500 font-medium">
                            {isProtected ? 'Full System Access' : `${permCount} Modules Assigned`}
                        </span>
                    </td>
                    <td className="p-4 whitespace-nowrap">
                        <span className={`px-2.5 py-1 text-xs font-bold rounded-full border ${role.status === 'Active' ? 'bg-green-50 text-green-700 border-green-200' : 'bg-red-50 text-red-700 border-red-200'}`}>
                            {role.status || 'Active'}
                        </span>
                    </td>
                    {(canUpdate || canDelete) && (
                        <td className="p-4 whitespace-nowrap text-sm font-medium">
                            <div className="flex items-center space-x-2">
                                {canUpdate && (
                                    <Tooltip content={isProtected ? "View Full Access" : "Edit Permissions"}>
                                        <button 
                                            onClick={() => openRoleModal(role)} 
                                            className={`w-8 h-8 flex items-center justify-center rounded-full transition-colors ${isProtected ? 'bg-gray-100 text-gray-400 cursor-not-allowed' : 'text-gray-500 hover:bg-blue-50 hover:text-blue-600'}`}
                                            disabled={isProtected}
                                        >
                                            <i className="ri-shield-key-line text-lg"></i>
                                        </button>
                                    </Tooltip>
                                )}
                                {canDelete && (
                                    <Tooltip content={isProtected ? "Cannot Delete System Role" : "Delete Role"}>
                                        <button 
                                            onClick={() => handleDelete(role)} 
                                            className={`w-8 h-8 flex items-center justify-center rounded-full transition-colors ${isProtected ? 'bg-gray-100 text-gray-400 cursor-not-allowed' : 'text-gray-500 hover:bg-red-50 hover:text-red-600'}`}
                                            disabled={isProtected}
                                        >
                                            <i className="ri-delete-bin-line text-lg"></i>
                                        </button>
                                    </Tooltip>
                                )}
                            </div>
                        </td>
                    )}
                    </tr>
                );
              })}
               {paginatedData.length === 0 && (
                <tr><td colSpan={4} className="text-center py-12 text-gray-500 italic">No custom roles defined.</td></tr>
               )}
            </tbody>
          </table>
      </div>
      <Pagination
          currentPage={currentPage}
          totalPages={totalPages}
          onPageChange={setCurrentPage}
          itemsPerPage={itemsPerPage}
          onItemsPerPageChange={setItemsPerPage}
          totalItems={totalItems}
          startIndex={startIndex}
          endIndex={endIndex}
      />
    </div>
  );
};

export default RoleManagement;

import React, { useState, useEffect } from 'react';
import { Role, Permissions, ModuleName, PermissionAction } from '../../types';

interface RoleModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (role: Omit<Role, 'id'> | Role) => void;
  role: Role | null;
}

const initialFormData: Omit<Role, 'id'> = {
  name: '',
  permissions: {},
  status: 'Active'
};

const MODULES: {key: ModuleName, label: string}[] = [
    { key: 'leads', label: 'Leads' },
    { key: 'customers', label: 'Customers' },
    { key: 'reminders', label: 'Reminders' },
    { key: 'vendors', label: 'Vendors' },
    { key: 'invoices', label: 'Invoices' },
    { key: 'users', label: 'User Management' },
    { key: 'roles', label: 'Role Management' },
    { key: 'settings', label: 'Settings & Config' },
];

const ACTIONS: PermissionAction[] = ['read', 'create', 'update', 'delete'];

const RoleModal: React.FC<RoleModalProps> = ({ isOpen, onClose, onSave, role }) => {
  const [formData, setFormData] = useState<Omit<Role, 'id'> | Role>(initialFormData);

  useEffect(() => {
    if (role) {
      setFormData({ ...role });
    } else {
      setFormData(initialFormData);
    }
  }, [role, isOpen]);

  if (!isOpen) return null;

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handlePermissionChange = (module: ModuleName, action: PermissionAction) => {
    setFormData(prev => {
        const currentPermissions = prev.permissions[module] || [];
        const newPermissions = currentPermissions.includes(action)
            ? currentPermissions.filter(p => p !== action)
            : [...currentPermissions, action];

        return {
            ...prev,
            permissions: {
                ...prev.permissions,
                [module]: newPermissions
            }
        };
    });
  };

  const toggleAllForModule = (module: ModuleName) => {
      setFormData(prev => {
          const current = prev.permissions[module] || [];
          const hasAll = current.length === ACTIONS.length;
          return {
              ...prev,
              permissions: {
                  ...prev.permissions,
                  [module]: hasAll ? [] : [...ACTIONS]
              }
          };
      });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name.trim()) return;
    onSave(formData);
  };

  return (
    <div className="fixed inset-0 bg-black/60 z-[100] flex justify-center items-center p-4 backdrop-blur-sm" onClick={onClose}>
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-3xl relative flex flex-col max-h-[90vh] overflow-hidden" onClick={e => e.stopPropagation()}>
         <button 
            onClick={onClose} 
            className="absolute top-4 right-4 w-10 h-10 bg-gray-100 rounded-full text-gray-500 flex items-center justify-center hover:bg-gray-200 transition-all hover:rotate-90 z-10"
        >
            <i className="ri-close-line text-2xl"></i>
        </button>

        <div className="p-6 border-b flex-shrink-0">
            <h3 className="text-xl font-bold text-gray-900">{role ? 'Edit Permissions' : 'Create Access Level'}</h3>
            <p className="text-sm text-gray-500 mt-1">Define what users in this role can see and do.</p>
        </div>

        <form onSubmit={handleSubmit} className="flex flex-col flex-grow overflow-hidden">
          <div className="flex-grow overflow-y-auto p-6 space-y-8 thin-scrollbar">

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                    <label className="block text-xs font-bold text-gray-400 uppercase tracking-wider mb-2">Role Title <span className="text-primary">*</span></label>
                    <input 
                        type="text" 
                        name="name" 
                        value={formData.name} 
                        onChange={handleChange} 
                        className="input-field-new" 
                        placeholder="e.g. Sales Executive"
                        required 
                    />
                </div>
                <div>
                    <label className="block text-xs font-bold text-gray-400 uppercase tracking-wider mb-2">Role Status</label>
                    <select 
                        name="status" 
                        value={formData.status} 
                        onChange={handleChange} 
                        className="input-field-new"
                    >
                        <option value="Active">Active</option>
                        <option value="Inactive">Inactive</option>
                    </select>
                </div>
            </div>

            <div>
              <div className="flex justify-between items-end mb-4">
                  <label className="text-xs font-bold text-gray-400 uppercase tracking-wider">Access Control Matrix</label>
                  <span className="text-[10px] text-gray-400 italic">Select checkboxes to grant specific permissions</span>
              </div>

              <div className="border border-gray-100 rounded-xl overflow-hidden shadow-sm">
                <table className="w-full text-sm">
                  <thead className="bg-gray-50 border-b border-gray-100">
                    <tr>
                      <th className="p-4 text-left font-bold text-gray-700">Module</th>
                      {ACTIONS.map(action => (
                        <th key={action} className="p-4 text-center font-bold text-gray-600 w-24 uppercase text-[10px] tracking-widest">{action}</th>
                      ))}
                      <th className="p-4 w-12"></th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-50">
                    {MODULES.map(module => (
                      <tr key={module.key} className="hover:bg-blue-50/30 transition-colors">
                        <td className="p-4">
                            <div className="flex flex-col">
                                <span className="font-semibold text-gray-900">{module.label}</span>
                            </div>
                        </td>
                        {ACTIONS.map(action => (
                          <td key={action} className="p-4 text-center">
                            <label className="inline-flex items-center cursor-pointer group">
                                <input
                                  type="checkbox"
                                  className="w-5 h-5 rounded border-gray-300 text-primary focus:ring-primary transition-all cursor-pointer"
                                  checked={formData.permissions[module.key]?.includes(action) || false}
                                  onChange={() => handlePermissionChange(module.key, action)}
                                />
                            </label>
                          </td>
                        ))}
                        <td className="p-4 text-center">
                            <button 
                                type="button" 
                                onClick={() => toggleAllForModule(module.key)}
                                className="text-primary hover:bg-primary/10 w-8 h-8 rounded-full transition-colors flex items-center justify-center"
                                title="Toggle All for this module"
                            >
                                <i className="ri-list-check-3 text-lg"></i>
                            </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          </div>

          <div className="flex justify-end items-center gap-3 bg-gray-50 p-6 border-t flex-shrink-0">
            <button type="button" onClick={onClose} className="px-6 py-2.5 bg-white border border-gray-300 text-gray-700 font-bold rounded-xl hover:bg-gray-100 transition-all text-sm shadow-sm">
              Discard Changes
            </button>
            <button type="submit" className="px-8 py-2.5 bg-primary text-white font-bold rounded-xl hover:bg-primary/90 transition-all text-sm shadow-lg shadow-primary/20 active:scale-95">
              {role ? 'Save Security Policy' : 'Create Role'}
            </button>
          </div>
        </form>
      </div>
       <style>{`
        .input-field-new {
            display: block;
            width: 100%;
            border-radius: 0.75rem;
            border: 1px solid #E5E7EB;
            box-shadow: 0 1px 2px 0 rgb(0 0 0 / 0.05);
            font-size: 0.875rem;
            line-height: 1.25rem;
            padding: 0.75rem 1rem;
            background-color: #fff;
            transition: all 0.2s;
        }
        .input-field-new:focus {
            outline: none;
            border-color: #c4161c;
            box-shadow: 0 0 0 4px rgba(196, 22, 28, 0.1);
        }
        .thin-scrollbar::-webkit-scrollbar { width: 6px; }
        .thin-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .thin-scrollbar::-webkit-scrollbar-thumb { background: #E5E7EB; border-radius: 10px; }
      `}</style>
    </div>
  );
};

