interface UserModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (user: Omit<User, 'id'> | User) => void;
  user: User | null;
}

const initialFormData: Omit<User, 'id'> = {
  name: '',
  username: '',
  email: '',
  roleId: '',
  role: '',
  status: 'Active',
  imageUrl: '',
};

const UserModal: React.FC<UserModalProps> = ({ isOpen, onClose, onSave, user }) => {
  const [formData, setFormData] = useState(initialFormData);
  const { roles } = useCrm();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [passwordError, setPasswordError] = useState('');


  useEffect(() => {
    if (user) {
      setFormData({
          ...user,
          roleId: user.roleId || '',
          role: user.role || ''
      });
    } else {
      setFormData({
        ...initialFormData,
        roleId: roles[0]?.id || '',
        role: roles[0]?.name || ''
      });
    }
    // Reset password fields on open
    setPassword('');
    setConfirmPassword('');
    setPasswordError('');
  }, [user, isOpen, roles]);

  if (!isOpen) return null;

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleRoleChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const selectedRoleId = e.target.value;
    const selectedRole = roles.find(r => String(r.id) === String(selectedRoleId));
    setFormData(prev => ({ 
        ...prev, 
        roleId: selectedRoleId, 
        role: selectedRole?.name || '' 
    }));
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
        const file = e.target.files[0];
        const reader = new FileReader();
        reader.onloadend = () => {
            setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
        };
        reader.readAsDataURL(file);
    }
  };

  const handleRemoveImage = () => {
    setFormData(prev => ({ ...prev, imageUrl: '' }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setPasswordError('');

    if (!user && !password) {
        setPasswordError('Password is required for new users.');
        return;
    }

    if (password && password !== confirmPassword) {
        setPasswordError('Passwords do not match.');
        return;
    }

    // Create a mutable copy to potentially add password
    const userToSave: any = { ...formData };

    if (password) {
        userToSave.password = password;
    }

    onSave(userToSave);
  };

  const avatarSrc = formData.imageUrl || generateAvatar(formData.name);

  return (
    <div className="fixed inset-0 bg-black bg-opacity-60 z-50 flex justify-center items-center p-4" onClick={onClose}>
