    return (
        <div className="space-y-4">
             <div className="flex justify-between items-center bg-gray-50 p-4 rounded-xl border">
                <h3 className="text-sm font-bold text-gray-700 uppercase tracking-widest">Recent Activity History</h3>
                <SearchInput value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-64" placeholder="Filter by name..." />
            </div>
            <div className="overflow-x-auto border border-gray-100 rounded-xl">
                <table className="w-full text-sm">
                    <thead className="bg-gray-50 border-b">
                        <tr>
                            <th className="p-3 text-left font-bold text-gray-500 uppercase text-[10px]">S.No</th>
                            <th className="p-3 text-left font-bold text-gray-500 uppercase text-[10px]">Reference File</th>
                            <th className="p-3 text-left font-bold text-gray-500 uppercase text-[10px]">Records</th>
                            <th className="p-3 text-left font-bold text-gray-500 uppercase text-[10px]">Actor</th>
                            <th className="p-3 text-left font-bold text-gray-500 uppercase text-[10px] cursor-pointer" onClick={() => requestSort('createdAt')}>
                                Date {sortConfig?.key === 'createdAt' && (sortConfig.direction === 'ascending' ? '↑' : '↓')}
                            </th>
                            <th className="p-3 text-center font-bold text-gray-500 uppercase text-[10px]">Action</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-50">
                        {paginatedData.map((item, i) => (
                            <tr key={item.id} className="hover:bg-blue-50/20 transition-colors">
                                <td className="p-3 text-gray-400 font-mono text-xs">{startIndex + i}</td>
                                <td className="p-3 font-semibold text-gray-700 truncate max-w-[200px]">{item.fileName}</td>
                                <td className="p-3 font-black text-primary">{item.totalLeads}</td>
                                <td className="p-3 text-gray-600 font-medium">{item.addedBy}</td>
                                <td className="p-3 text-gray-500 text-xs">{new Date(item.createdAt).toLocaleString()}</td>
                                <td className="p-3 text-center">
                                    <button onClick={() => handleDelete(item)} className="w-8 h-8 rounded-full text-gray-300 hover:text-red-500 hover:bg-red-50 transition-colors">
                                        <i className="ri-delete-bin-line"></i>
                                    </button>
                                </td>
