import React from 'react';
import { useNavigate } from 'react-router-dom';
import { useCrm } from '../../hooks/useCrm';
import { Notification } from '../../types';

interface NotificationPanelProps {
  onClose: () => void;
}

const NotificationPanel: React.FC<NotificationPanelProps> = ({ onClose }) => {
  const { notifications, markNotificationAsRead, markAllNotificationsAsRead, getUnreadNotificationCount } = useCrm();
  const navigate = useNavigate();
  const unreadCount = getUnreadNotificationCount();

  const handleNotificationClick = (notification: Notification) => {
    markNotificationAsRead(notification.id);
    if (notification.linkTo) {
      navigate(notification.linkTo);
    }
    onClose();
  };

  const handleMarkAllRead = (e: React.MouseEvent) => {
      e.preventDefault();
      markAllNotificationsAsRead();
  };

  const formatTimeAgo = (dateString: string) => {
    const date = new Date(dateString);
    const now = new Date();
    const seconds = Math.floor((now.getTime() - date.getTime()) / 1000);

    let interval = seconds / 31536000;
    if (interval > 1) return `${Math.floor(interval)}y ago`;
    interval = seconds / 2592000;
    if (interval > 1) return `${Math.floor(interval)}mo ago`;
    interval = seconds / 86400;
    if (interval > 1) return `${Math.floor(interval)}d ago`;
    interval = seconds / 3600;
    if (interval > 1) return `${Math.floor(interval)}h ago`;
    interval = seconds / 60;
    if (interval > 1) return `${Math.floor(interval)}m ago`;
    return `${Math.floor(seconds)}s ago`;
  }

  const getIconBgClass = (iconColor?: string) => {
      // Defensive check to prevent "includes of undefined" error
      if (!iconColor) return 'bg-gray-100';
      if (iconColor.includes('blue')) return 'bg-blue-100';
      if (iconColor.includes('yellow')) return 'bg-yellow-100';
      if (iconColor.includes('purple')) return 'bg-purple-100';
      if (iconColor.includes('green')) return 'bg-green-100';
      if (iconColor.includes('red')) return 'bg-red-100';
      return 'bg-gray-100';
  };

  return (
    <div className="absolute right-0 mt-2 w-80 sm:w-96 bg-white rounded-lg shadow-lg border z-50 flex flex-col max-h-[calc(100vh-80px)]">
      <div className="flex justify-between items-center p-4 border-b flex-shrink-0">
        <h3 className="text-lg font-semibold text-gray-800">Notifications</h3>
        {unreadCount > 0 && <button onClick={handleMarkAllRead} className="text-sm font-medium text-primary hover:underline">Mark all as read</button>}
      </div>
      <div className="overflow-y-auto thin-scrollbar flex-grow">
        {notifications.length > 0 ? (
          notifications.map(notification => (
            <button
              key={notification.id}
              onClick={() => handleNotificationClick(notification)}
              className={`w-full text-left p-4 flex items-start gap-4 hover:bg-gray-50 border-b border-gray-100 last:border-b-0 ${!notification.isRead ? 'bg-primary/5' : ''}`}
            >
              <div className={`flex-shrink-0 h-10 w-10 flex items-center justify-center rounded-full ${getIconBgClass(notification.iconColor)}`}>
                <i className={`${notification.icon || 'ri-notification-3-line'} text-lg ${notification.iconColor || 'text-gray-500'}`}></i>
              </div>
              <div className="flex-grow min-w-0">
                <p className="font-semibold text-gray-800 text-sm truncate">{notification.title}</p>
                <p className="text-sm text-gray-600 line-clamp-2">{notification.content}</p>
                <p className="text-xs text-gray-400 mt-1">{formatTimeAgo(notification.createdAt)}</p>
              </div>
              {!notification.isRead && (
                 <div className="flex-shrink-0 w-2.5 h-2.5 bg-primary rounded-full mt-1.5" title="Unread"></div>
              )}
            </button>
          ))
        ) : (
          <div className="text-center p-8 text-gray-500 flex flex-col items-center justify-center h-full">
            <i className="ri-notification-off-line text-5xl text-gray-300"></i>
            <p className="mt-3 font-medium">No notifications yet.</p>
            <p className="text-sm text-gray-400">We'll let you know when something new comes up.</p>
          </div>
        )}
      </div>
      <div className="p-2 border-t text-center flex-shrink-0">
        <button className="text-sm font-medium text-primary hover:underline">View All Notifications</button>
      </div>
    </div>
  );
};

export default NotificationPanel;

