        const headers = lines[0].split(',');
        const leadsArray = [];

        for(let i = 1; i < lines.length; i++) {
            if(!lines[i].trim()) continue;
            const values = lines[i].split(',');
            const lead: any = {};
            headers.forEach((header, index) => {
                lead[header.trim().toLowerCase()] = values[index]?.trim();
            });
            leadsArray.push(lead);
