  const sendEmail = async (data: any) => { 
    await api.communications.sendEmail(data); 
    const eData = await api.communications.getEmails(data.leadId);
    setEmails(prev => [...prev.filter(e => String(e.leadId) !== String(data.leadId)), ...eData]);
