  const getWhatsAppMessagesForLead = useCallback((leadId: string | number) => whatsappMessages.filter(m => String(m.leadId) === String(leadId)), [whatsappMessages]);
  const sendWhatsAppMessage = async (leadId: any, content: string) => { 
